/* WIMORO — views module */

'use strict';
/* ===================== Emblèmes de rang (dessin original) ===================== */
let EMB=0;
const GW='stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" fill="none"';
const GLYPH=['<circle cx="24" cy="23.5" r="4.5" fill="#fff" opacity=".92"/>',`<path d="M17 27l7-6 7 6" ${GW}/>`,`<path d="M17 23l7-6 7 6M17 30l7-6 7 6" ${GW}/>`,`<path d="M17 19l7-6 7 6M17 25.5l7-6 7 6M17 32l7-6 7 6" ${GW}/>`,'<path d="M24 12.5l7.5 10.5L24 33.5l-7.5-10.5Z" fill="#fff" opacity=".95"/>','<path d="M19 14l5.2 8.5L19 31l-5.2-8.5ZM29 14l5.2 8.5L29 31l-5.2-8.5Z" fill="#fff" opacity=".95"/>','<path d="M24 12l8.5 9.5H27V33h-6V21.5h-5.5Z" fill="#fff" opacity=".95"/>','<path d="M14.5 31l2.2-14.5 4.8 7.2L24 13.5l2.5 10.2 4.8-7.2L33.5 31Z" fill="#fff" opacity=".95"/>','<path d="M24 11.5l3.4 7 7.6 1.1-5.5 5.4 1.3 7.6L24 29l-6.8 3.6 1.3-7.6-5.5-5.4 7.6-1.1Z" fill="#fff"/>'];
function emb(t,d=0,cls=''){const T=TIERS[t],u='eg'+(++EMB);const pips=t===8?'':[0,1,2].map(i=>`<rect x="${12.5+i*8.5}" y="48" width="6" height="4" rx="2" ${i<=d?`fill="${T.c[1]}"`:'style="fill:var(--fill-2)"'}/>`).join('');
 const rays=t===8?Array.from({length:12},(_,i)=>{const a=i*Math.PI/6+Math.PI/12;return `<path d="M${(24+17*Math.cos(a)).toFixed(1)} ${(23+17*Math.sin(a)).toFixed(1)}L${(24+23.5*Math.cos(a)).toFixed(1)} ${(23+23.5*Math.sin(a)).toFixed(1)}" stroke="${T.c[1]}" stroke-width="2.4" stroke-linecap="round"/>`;}).join(''):'';
 return `<svg class="emb ${cls}" viewBox="0 0 48 54" aria-hidden="true"><defs><linearGradient id="${u}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${T.c[0]}"/><stop offset="1" stop-color="${T.c[1]}"/></linearGradient></defs>${rays}<path d="M24 2 43 13v20L24 44 5 33V13Z" fill="url(#${u})"/><path d="M24 2 43 13 24 23 5 13Z" fill="#fff" opacity=".2"/>${GLYPH[t]}${pips}</svg>`;}
const rk=(t,d)=>`<span class="rk${t===8?' r8':''}">${emb(t,d)}${rankName(t,d)}</span>`;

/* ===================== Petits composants ===================== */
function meU(){const r=myRank();return {n:S.me.n,t:r.t,d:r.d,tone:'me'};}
const userOf=u=>u==='me'?meU():(USERS[u]||fantome(u));
const uHref=u=>u==='me'?'#profil':'#joueur-'+u;
function avH(u,size,tag='a'){const U=userOf(u);const css=(size?`width:${size}px;height:${size}px;font-size:${Math.round(size*.4)}px;`:'')+(u==='me'?`background:${S.me.color};`:'');const st=css?` style="${css}"`:'';return `<${tag} class="av${avClass(u)} ${u==='me'?'t-me':'t'+U.tone}"${tag==='a'?` href="${uHref(u)}" aria-label="${esc(u==='me'?_t('Mon profil'):_t('Profil de {0}',[U.n]))}"`:''}${st}>${avInner(u,size||32)}</${tag}>`;}
function richText(t){return esc(t).replace(/@([\w.]+)/g,'<span class="mention">@$1</span>').replace(/#([a-z0-9-]+)/g,(s,id)=>MK[id]?`<a class="mlink" href="#marche-${id}">${esc(MK[id].short)} <b data-mp="${id}">${F.pct(MK[id].p)}</b></a>`:s);}
function gateBtn(g,label,cls,extra=''){if(can(g))return `<button class="btn ${cls}" data-a="${g}" ${extra}>${label}</button>`;return `<button class="btn ${cls}" data-a="lock" data-g="${g}" ${extra}>${label} <span class="lk">${ic('lock',10)} ${TIERS[GATES[g].t].name}</span></button>`;}
/* C13 : sur la page d'un marché, une seule variation est affichée : celle de la période choisie, nommée. */
const perLab=()=>({'1 h':_t('sur 1 heure'),'6 h':_t('sur 6 heures'),'1 j':_t('sur 24 heures'),'1 sem.':_t('sur 7 jours'),'Tout':_t('depuis l’ouverture')})[S.ui.tf]||'';
const perDelta=m=>{if(S.ui.tf==='1 j')return Math.round(m.p-m.d0);const a=series(m,S.ui.tf);return Math.round(a[a.length-1]-a[0]);};
const ptsLong=(d,suf)=>{const r=Math.round(d),a=Math.abs(r);return `${_t("{0} point{1} {2}",[bidi((r>=0?'+':'−')+a),a>1?'s':'',suf])}`;};
function followBtn(u){const on=S.me.following.includes(u);return `<button class="btn ${on?'b-soft':'b-ghost'} sm" data-a="follow-user" data-u="${u}">${on?_t("Suivi"):_t("Suivre")}</button>`;}
const posOf=(mid,s)=>S.me.positions.find(p=>p.m===mid&&p.s===s)||{sh:0,avg:0};
/* Espaces insécables : règles françaises (chiffre + mot, espace avant ? ! : ; % $) uniquement en français.
   En anglais et en hébreu, seul un nombre reste collé à son unité (« 45 s », « 63 % »), sans souder les mots qui suivent. */
const FIX_UNIT=/(\d) (?=(?:[%¢]|(?:ms|min|s|h|d|XP|pts?)(?![\w\u0590-\u05FF])|[\u0590-\u05FF]{1,3}[׳״]))/g;
function fixText(root){if(!root)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;
 if(LANG!=='fr'){while((n=w.nextNode())){const v=n.nodeValue;if(!/\d /.test(v))continue;const nv=v.replace(FIX_UNIT,'$1 ');if(nv!==v)n.nodeValue=nv;}return;}
 while((n=w.nextNode())){const v=n.nodeValue;if(!/\d |\s[?!:;%$¢»]|« /.test(v))continue;const nv=v.replace(/(\d) (?=[\d$%¢A-Za-zÀ-ÿ])/g,'$1 ').replace(/ ([?!:;%$¢»])/g,' $1').replace(/« /g,'« ');if(nv!==v)n.nodeValue=nv;}}

/* ===================== Traînée des mises ===================== */
function barH(b,isNew){return `<span class="b ${b.s===2?'e':b.s?'o':'n'}${b.me?' me':''}${isNew?' new':''}"><i style="height:${(6+b.a*42).toFixed(1)}%"></i></span>`;}
function trailFill(el){const id=el.dataset.trail;
 if(id!=='flash'&&S.ui.tmode!=='bars'){const m=MK[id];if(m&&m.ph&&m.ph.length>1){const L=lineSVG(m.ph.slice(-(el.classList.contains('big')?120:70)),m.p>=m.d0);   /* la couleur suit la variation sur 24 h affichée à côté */el.classList.add('tl');el.innerHTML=L.svg+`<i class="tdot" style="top:${L.top.toFixed(1)}%;background:${L.col}"></i>`;return;}}
 el.classList.remove('tl');const src=id==='flash'?G(S.ui.fgame).bets:(MK[id]?MK[id].bets:[]);const cap=Math.max(8,Math.floor((el.clientWidth||300)/5));el.dataset.cap=cap;el.innerHTML=src.slice(-cap).map(b=>barH(b,false)).join('');}
function trailPush(id,b){if(id!=='flash'&&S.ui.tmode!=='bars')return;$$(`[data-trail="${id}"]`).forEach(el=>{el.insertAdjacentHTML('beforeend',barH(b,true));const cap=+el.dataset.cap||60;while(el.children.length>cap)el.firstElementChild.remove();});}
function mountTrails(root=document){$$('[data-trail]',root).forEach(trailFill);if(root.dataset&&root.dataset.trail)trailFill(root);}
/* fiche marché : la seconde courbe vit dans un <details> replié ; à l'ouverture, elle est redessinée à sa vraie largeur */
document.addEventListener('toggle',e=>{const d=e.target;if(d&&d.matches&&d.matches('details.trdet')&&d.open)mountTrails(d);},true);

/* ===================== Messages ===================== */
const REM=['🔥','👀','💸','🎯'];
function reactsInner(x){return REM.filter(e=>x.r[e]).map(e=>`<button class="${x.my.includes(e)?'on':''}" data-a="react" data-id="${x.id}" data-e="${e}">${e} ${x.r[e]}</button>`).join('')+`<button class="add" data-a="react-pal" aria-label="${_t("Réagir")}">${ic('smile',14)}</button><span class="pal">${REM.filter(e=>!x.r[e]).map(e=>`<button data-a="react" data-id="${x.id}" data-e="${e}">${e}</button>`).join('')}</span>`;}
function fcText(x){const n=x.followers||0;return n===0?(x.u==='me'?_t("Personne ne l’a encore suivie"):_t("Sois le premier à la suivre")):n===1?_t("1 personne l’a suivie"):F.int(n)+_t(" personnes l’ont suivie");}
function betHTML(x){const b=x.bet,m=MK[b.m],o=b.s==='oui',mine=x.u==='me';if(!m)return '';return `<div class="betc ${o?'':'non'}"><div class="bl"><b class="num">${F.usd0(b.amt)}</b><span>${_t("sur {0} à {1}",[o?_t("Oui"):_t("Non"),F.c(b.price)])}</span></div><a class="bm" href="#marche-${m.id}">${esc(m.q)}</a><div class="bf">${mine?`<span class="fc">${_t("Ta mise")}</span>`:(can('follow')?`<button class="btn ${o?'b-yes':'b-no'} sm" data-a="follow-bet" data-id="${x.id}">${_t("Suivre cette mise")}</button>`:`<button class="btn ${o?'b-yes':'b-no'} sm" data-a="lock" data-g="follow">${_t("Suivre cette mise")} <span class="lk">${_t("{0} Argent",[ic('lock',10)])}</span></button>`)}<span class="fc" data-fc="${x.id}">${fcText(x)}</span></div></div>`;}
function sigHTML(x){const g=x.sig,m=MK[g.m],o=g.s==='oui';if(!m)return '';return `<div class="sig ${o?'':'non'}" data-id="${x.id}"><div class="sg-h">${_t("<b>Signal de foule</b>")}<span>${hhmm(x.at)}</span></div><p>${_t("{0} personnes ont acheté {1} sur « {2} » en {3} minutes.",[F.int(g.n),o?_t("Oui"):_t("Non"),esc(m.short),g.mins])}</p><div class="trail sm" data-trail="${m.id}"></div><div class="sg-f"><span>${_t("De {0} % à {1} % en {2} min",[g.from,g.to,g.mins*2])}</span><a class="btn b-ink sm" href="#marche-${m.id}">${_t("Voir le marché")}</a></div></div>`;}
function msgH(x){if(x.k==='evt')return `<div class="evt" data-id="${x.id}">${x.rt!=null?emb(x.rt,x.rd):''}<span>${richText(x.text)}</span></div>`;if(x.k==='sig')return sigHTML(x);
 const U=userOf(x.u),mine=x.u==='me';return `<div class="msg${mine?' mine':''}" data-id="${x.id}">${avH(x.u)}<div class="mb"><div class="mh"><a class="un" href="${uHref(x.u)}">${esc(U.n)}</a>${tagH(x.u)}${rk(U.t,U.d)}<span class="tm">${hhmm(x.at)}</span></div>${x.text?`<div class="tx">${richText(x.text)}</div>`:''}${x.k==='bet'?betHTML(x):x.k==='ana'?anaCardH(x):''}<div class="reacts${REM.some(e=>x.r[e])?'':' empty'}" data-re="${x.id}">${reactsInner(x)}</div></div></div>`;}
const rsum=x=>Object.values(x.r).reduce((a,b)=>a+b,0)+(x.followers||0);
function feedH(rid){let L=room(rid).msgs;if(rid.startsWith('m:')&&S.ui.mtab==='top')L=L.filter(x=>x.k==='msg'||x.k==='bet'||x.k==='ana').slice().sort((a,b)=>rsum(b)-rsum(a)).slice(0,15).reverse();return L.slice(-60).map(msgH).join('');}
function composerH(rid){return `<div class="composer"><form class="cin" data-form="${rid}"><input data-in="${rid}" placeholder="${esc(composerPh(rid))}" maxlength="280" autocomplete="off" enterkeyhint="send" aria-label="${_t("Message")}"><span class="cc" data-cc aria-live="polite"></span><button class="send" type="submit" aria-label="${_t("Envoyer")}">${ic('send',17,'#fff')}</button></form><div class="ctools">${gateBtn('share',ic('share',15)+_t(" Partager une mise"),'b-ghost sm',`data-room="${rid}"`)}<button class="btn b-ghost sm" data-a="cite" data-room="${rid}">${_t("{0} Citer un marché",[ic('hash',15)])}</button><span class="xpc">${_t("+2 XP par message")}</span></div></div>`;}
function chatH(rid,cls,head){return `<section class="pn chat ${cls}" data-chatbox="${rid}">${head}<div class="feed" data-room="${rid}">${feedH(rid)}</div>${composerH(rid)}</section>`;}
function unr(r){const n=(S.rooms[r]||{}).unread||0;return n?`<span class="unr">${n>9?'9+':n}</span>`:'';}
function addMsg(rid,x){if(rid.startsWith('m:')&&!MK[rid.slice(2)]){console.warn('[chat] message ignoré : marché inconnu',rid);return;}const r=room(rid);r.msgs.push(x);if(r.msgs.length>160)r.msgs.shift();
 if(rid.startsWith('m:')){const m=MK[rid.slice(2)];m.msgs++;$$(`[data-mmsg="${m.id}"]`).forEach(el=>el.textContent=F.int(m.msgs));}
 const feeds=$$(`.feed[data-room="${rid}"]`);if(feeds.length)feeds.forEach(f=>appendTo(f,x));else if(rid!=='vip'){r.unread++;$$(`[data-unread="${rid}"]`).forEach(el=>el.innerHTML=unr(rid));}}
function appendTo(feed,x){if(feed.dataset.room.startsWith('m:')&&S.ui.mtab==='top'&&x.u!=='me')return;const stick=feed.scrollHeight-feed.scrollTop-feed.clientHeight<140||x.u==='me'||Date.now()-(+feed.dataset.down||0)<900;feed.insertAdjacentHTML('beforeend',msgH(x));const el=feed.lastElementChild;fixText(el);mountTrails(el);
 /* C21 : en retirant les plus anciens (70 messages au plus), la position de lecture est conservée ; si on lit plus haut, une pastille annonce les nouveaux messages */
 if(feed.children.length>70){if(stick){while(feed.children.length>70)feed.firstElementChild.remove();feed._fr=0;}
  else{const ref=feed.children[feed.children.length-70],y0=ref.getBoundingClientRect().top;while(feed.children.length>70)feed.firstElementChild.remove();const adj=ref.getBoundingClientRect().top-y0+(feed._fr||0),t=feed.scrollTop;feed.scrollTop=t+adj;feed._fr=adj-(feed.scrollTop-t);}}
 if(stick){feed.dataset.down=Date.now();feed.scrollTo({top:feed.scrollHeight,behavior:doux()});feedPill(feed,false);}else feedPill(feed,true);}
function feedPill(feed,on){const box=feed.parentElement;if(!box)return;let w=box.querySelector('.nm-w');if(!on){if(w)w.remove();return;}if(w)return;w=document.createElement('div');w.className='nm-w';w.innerHTML=`<button type="button" class="nm-pill" data-a="feed-down">${_t('Nouveaux messages')} <span aria-hidden="true">↓</span></button>`;feed.insertAdjacentElement('afterend',w);}
document.addEventListener('scroll',e=>{const f=e.target;if(f&&f.classList&&f.classList.contains('feed')&&f.scrollHeight-f.scrollTop-f.clientHeight<60)feedPill(f,false);},{capture:true,passive:true});
/* un geste de défilement annule la descente automatique */
for(const t of ['wheel','touchmove'])document.addEventListener(t,e=>{const f=e.target.closest?e.target.closest('.feed'):null;if(f&&f.dataset.down)delete f.dataset.down;},{capture:true,passive:true});
/* compteur discret à l'approche de la limite de 280 caractères */
function ccUpd(i){const c=i.parentElement.querySelector('[data-cc]');if(!c)return;const n=i.value.length;c.textContent=n>=240?bidi(n+' / 280'):'';c.classList.toggle('lim',n>=270);}
document.addEventListener('input',e=>{const i=e.target;if(i&&i.dataset&&i.dataset.in!==undefined)ccUpd(i);});
document.addEventListener('submit',e=>{const i=e.target.querySelector?e.target.querySelector('[data-in]'):null;if(i)setTimeout(()=>ccUpd(i),0);},true);
function refreshReacts(x){$$(`[data-re="${x.id}"]`).forEach(el=>{const mm=el.closest('.msg');el.innerHTML=reactsInner(x);el.classList.toggle('empty',!REM.some(e=>x.r[e]));if(mm)mm.classList.remove('palopen');});}
function setFc(x){$$(`[data-fc="${x.id}"]`).forEach(el=>el.textContent=fcText(x));}

/* ===================== Mises à jour en direct ===================== */
function updateMarket(m,old){const ch=old===undefined?0:Math.round(m.p)-Math.round(old);if(m.ph){m.ph.push(m.p);if(m.pht)m.pht.push(now());if(m.ph.length>160){m.ph.shift();if(m.pht)m.pht.shift();}if(S.ui.tmode!=='bars')$$(`[data-trail="${m.id}"]`).forEach(trailFill);}
 $$(`[data-mp="${m.id}"]`).forEach(el=>{const v=F.pct(m.p);if(el.textContent!==v){el.textContent=v;if(ch){el.classList.remove('tick-up','tick-dn');void el.offsetWidth;el.classList.add(ch>0?'tick-up':'tick-dn');}}});
 const d=m.p-m.d0;$$(`[data-md="${m.id}"]`).forEach(el=>{el.textContent=el.dataset.long?ptsLong(d,el.dataset.long):F.pts(d);el.classList.toggle('up',d>=0);el.classList.toggle('dn',d<0);});
 $$(`[data-mdp="${m.id}"]`).forEach(el=>{const pd=perDelta(m);el.textContent=ptsLong(pd,perLab());el.classList.toggle('up',pd>=0);el.classList.toggle('dn',pd<0);});
 $$(`[data-mc="${m.id}"]`).forEach(el=>el.textContent=F.c(m.p));$$(`[data-mcn="${m.id}"]`).forEach(el=>el.textContent=F.c(100-m.p));$$(`[data-mx="${m.id}"]`).forEach(el=>el.textContent=F.mult(el.dataset.side==='oui'?m.p:100-m.p));
 $$(`[data-mv="${m.id}"]`).forEach(el=>el.textContent=F.compact(m.vol));$$(`[data-people="${m.id}"]`).forEach(el=>el.textContent=F.int(m.people));
 if(S.ui.ticket.m===m.id)updNums('page');if(S.ui.sheet&&S.ui.sheet.m===m.id)updNums('sheet');if(typeof ordersCheck==='function')ordersCheck(m);}
function markHot(m){$$(`[data-row="${m.id}"]`).forEach(el=>el.classList.add('hot'));setTimeout(()=>{if(m.hotUntil<=now())$$(`[data-row="${m.id}"]`).forEach(el=>el.classList.remove('hot'));},90500);}
function tweenMoney(el,to){const from=parseFloat(el.dataset.v),full=el.classList.contains('balbig');el.dataset.v=to;if(isNaN(from)||Math.abs(from-to)<.005){el.textContent=F.bal(to,full);return;}const t0=performance.now(),D=600;const step=t=>{const k=Math.min(1,(t-t0)/D),e=1-Math.pow(1-k,3);el.textContent=F.bal(from+(to-from)*e,full);if(k<1)requestAnimationFrame(step);};requestAnimationFrame(step);el.classList.remove('pulse');void el.offsetWidth;el.classList.add('pulse');}
function updateHeader(){const r=myRank(),pg=progress(),ch=$('[data-rankchip]');if(ch){const key=r.t+'-'+r.d;if(ch.dataset.key!==key){ch.dataset.key=key;ch.innerHTML=`${emb(r.t,r.d)}<span class="rt"><b>${rankName(r.t,r.d)}</b><span class="xb"><i style="width:${pg.pct}%"></i></span></span>`;}else{const i=ch.querySelector('.xb i');if(i)i.style.width=pg.pct+'%';}ch.classList.toggle('blocked',!!(pg.blocked&&pg.nx));ch.title=pg.nx?(pg.blocked?`${_t("XP suffisante pour {0} : il te manque {1}",[rankName(pg.nx.t,0),missingTxt(pg)])}`:`${_t("Plus que {0} pour {1}",[F.xp(pg.left),rankName(pg.nx.t,pg.nx.d)])}`):_t("Rang maximal");}
 $$('[data-bal]').forEach(el=>tweenMoney(el,S.me.balance));$$('[data-bal-plain]').forEach(el=>el.textContent=F.bal(S.me.balance,true));$$('[data-me-ini]').forEach(el=>{el.innerHTML=avInner('me',32);el.classList.toggle('av-img',!!photoOf('me'));el.style.background=S.me.color;});$$('.bell').forEach(b=>b.classList.toggle('muted',(S.me.tmode||'imp')==='none'));updateBell();if(typeof rgSync==='function')rgSync();}
function updateBell(){const n=S.me.logged?S.me.notifs.filter(x=>!x.read).length:0;$$('[data-nbadge]').forEach(el=>el.textContent=n?(n>9?'9+':n):'');$$('[data-ndot]').forEach(el=>el.classList.toggle('hide',!n));$$('.bell').forEach(b=>b.setAttribute('aria-label',n?`${_t('Notifications')} (${n})`:_t('Notifications')));}
function refreshLive(){const pf=portfolio();$$('[data-live="profit"]').forEach(el=>{el.textContent=F.signed(pf.profit);el.classList.toggle('pl-up',pf.profit>0.004);el.classList.toggle('pl-dn',pf.profit<-0.004);});$$('[data-live="pvalue"]').forEach(el=>el.textContent=F.usd(pf.value));$$('[data-live="punreal"]').forEach(el=>{el.textContent=F.signed(pf.unreal);el.className='num t-4 '+plc(pf.unreal);});
 for(const p of S.me.positions){const k=p.m+'-'+p.s,m=MK[p.m],pr=p.s==='oui'?m.p:100-m.p;$$(`[data-pv="${k}"]`).forEach(el=>el.textContent=F.usd(posValue(p)));$$(`[data-ppr="${k}"]`).forEach(el=>el.textContent=F.c(pr));$$(`[data-ppnl="${k}"]`).forEach(el=>{const v=posPnl(p);el.textContent=F.signed(v);el.classList.toggle('pl-up',v>0.004);el.classList.toggle('pl-dn',v<-0.004);});}
 $$('[data-rsplit]').forEach(el=>{const m=MK[el.dataset.rsplit];el.style.width=clamp(Math.round(m.p+(hash(m.id)%13)-5),6,94)+'%';});}

/* ===================== Superpositions ===================== */
/* Textes courts : un titre ou un texte d'une seule phrase ne finit pas par un point (notifications éphémères, panneau des
   notifications). Un texte de plusieurs phrases garde les siens. Appliqué à l'affichage, pour que les notifications déjà
   enregistrées et celles du serveur suivent la même règle ; les marques de sens d'écriture finales restent en place. */
function sansPoint(s){s=String(s==null?'':s);const m=/^([\s\S]*?[^.])\.([\u200e\u200f\u2066-\u2069]*)$/.exec(s);return !m||/[.!?…]\s/.test(m[1])?s:m[1]+m[2];}
function toast(o){const {title,text='',sub='',icon='info',tone='',href='',dur=4200}=o;if(typeof toastAllowed==='function'&&!toastAllowed(o))return;const box=$('#toasts');if(!box)return;const t=document.createElement('div');t.className='toast '+tone;t.innerHTML=`<span class="ti">${ic(icon,16)}</span><div><b>${esc(sansPoint(title))}</b>${text?`<small>${esc(sansPoint(text))}</small>`:''}${sub?`<small class="tsub">${ic('shield',12)}<span>${esc(sub)}</span></small>`:''}</div><button class="tx" aria-label="${_t("Masquer la notification")}">${ic('x',14,'currentColor',2.4)}</button>`;fixText(t);t.addEventListener('click',e=>{if(e.target.closest('.tx')){kill();return;}if(href)location.hash=href;kill();});box.appendChild(t);const mx=innerWidth<=879?1:3;while(box.children.length>mx)box.firstElementChild.remove();let gone=false;const kill=()=>{if(gone)return;gone=true;t.classList.add('out');setTimeout(()=>t.remove(),300);};setTimeout(kill,dur);}
function floatXP(text,ev){let x,y;if(ev&&ev.clientX!=null){x=ev.clientX;y=ev.clientY-12;}else{const c=$('[data-rankchip]');const r=c&&c.getBoundingClientRect();if(r&&r.width){x=r.left+r.width/2;y=r.bottom+16;}else{x=innerWidth/2;y=120;}}const el=document.createElement('div');el.className='fxp';el.textContent=text;el.style.left=x+'px';el.style.top=y+'px';document.body.appendChild(el);setTimeout(()=>el.remove(),1250);const c=$('[data-rankchip]');if(c){c.classList.remove('pulse');void c.offsetWidth;c.classList.add('pulse');}}
function confetti(n=40,colors=['#2448FF','#F59A0B','#14161B','#7EE0D6','#F7D774']){/* FL6 */if(document.hidden||matchMedia('(prefers-reduced-motion: reduce)').matches)return;if(innerWidth<=879)n=Math.min(n,24);const cx=innerWidth/2,cy=innerHeight*.42;for(let i=0;i<n;i++){const c=document.createElement('i');c.className='cf';const a=R()*Math.PI*2,dist=160+R()*320;c.style.left=cx+'px';c.style.top=cy+'px';c.style.background=pick(colors);c.style.setProperty('--dx',Math.cos(a)*dist+'px');c.style.setProperty('--dy',Math.sin(a)*dist+260*R()+'px');c.style.setProperty('--r',(R()*720-360)+'deg');c.style.animationDelay=(R()*.15)+'s';document.body.appendChild(c);setTimeout(()=>c.remove(),1900);}}
function rankUp(r){ovRemember();const old=$('.rankup');if(old)old.remove();const nx=nextStep(r);const ov=document.createElement('div');ov.className='rankup';ov.setAttribute('role','dialog');ov.innerHTML=`<div class="rays"></div><div class="rc">${emb(r.t,r.d)}<div class="k">${_t("Nouveau rang")}</div><h2>${rankName(r.t,r.d)}</h2><p>${nx?`${_t("Prochain objectif : {0}{1}",[rankName(nx.t,nx.d),nx.tier?_t(", avec de nouvelles conditions."):'.'])}`:_t("Tu es au sommet de Wimoro.")}</p><div class="ra"><a class="btn b-white lg" href="#rang" data-a="rankup-close">${_t("Voir mon rang")}</a><button class="btn b-ink lg" data-a="rankup-close">${_t("Continuer")}</button></div></div>`;document.body.appendChild(ov);fixText(ov);confetti(70,[TIERS[r.t].c[0],TIERS[r.t].c[1],'#fff','#2448FF']);}
/* C11 : fenêtres et panneaux plein écran (#ov, recherche, nouveau rang). Tant que l'un d'eux est ouvert, l'arrière-plan ne défile plus,
   le focus entre dans la fenêtre et y reste (Tab), puis revient au bouton d'origine à la fermeture. Échap et le clic à côté ferment toujours. */
const FOCUSABLE='a[href],button:not([disabled]),input:not([disabled]):not([type="hidden"]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
let OVFROM=null,OVON=false,LASTC=null,LASTCT=0;
const topOverlay=()=>$('.rankup')||$('#sov')||$('#ov');
const ovBox=o=>o.id==='ov'?o.querySelector('.modal'):o.id==='sov'?o.querySelector('.sov-in'):o.querySelector('.rc')||o;
document.addEventListener('click',e=>{const t=e.target.closest?e.target.closest('a,button,[data-a],[tabindex]'):null;if(t&&!t.closest('#ov,#sov,.rankup')){LASTC=t;LASTCT=performance.now();}},true);
function ovRemember(){if(topOverlay())return;const a=document.activeElement;OVFROM=LASTC&&performance.now()-LASTCT<1200?LASTC:(a&&a!==document.body?a:null);}
function ovFocusBack(el){if(!el)return;let t=document.contains(el)?el:null;
 if(!t&&el.dataset&&el.dataset.a){let sel=`[data-a="${el.dataset.a}"]`;for(const k of ['m','s','id','v','g','ctx','u'])if(el.dataset[k]!==undefined)sel+=`[data-${k}="${String(el.dataset[k]).replace(/["\\]/g,'')}"]`;try{t=$(sel);}catch(e){}}
 if(t&&!t.matches('input:not([type=checkbox]):not([type=radio]),textarea,select'))try{t.focus({preventScroll:true});}catch(e){}}
function ovSync(){const o=topOverlay(),de=document.documentElement;
 if(o&&!OVON){OVON=true;de.style.setProperty('--sbw',Math.max(0,innerWidth-de.clientWidth)+'px');de.classList.add('lock');}
 else if(!o&&OVON){OVON=false;de.classList.remove('lock');const el=OVFROM;OVFROM=null;ovFocusBack(el);}
 if(o){if(!o.dataset.tm){o.dataset.tm='1';o.addEventListener('touchmove',e=>{if(e.target===o||o.classList.contains('rankup'))e.preventDefault();},{passive:false});}
  const b=ovBox(o);if(b&&!b.contains(document.activeElement)){if(!b.hasAttribute('tabindex'))b.setAttribute('tabindex','-1');try{b.focus({preventScroll:true});}catch(e){}}}}
new MutationObserver(ovSync).observe(document.body,{childList:true});
document.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const o=topOverlay();if(!o)return;const box=ovBox(o);if(!box)return;const L=[...box.querySelectorAll(FOCUSABLE)].filter(x=>x.getClientRects().length&&!x.closest('[inert]'));
 if(!L.length){e.preventDefault();return;}const a=document.activeElement,first=L[0],last=L[L.length-1];
 if(!box.contains(a)||a===box){e.preventDefault();(e.shiftKey?last:first).focus();}else if(e.shiftKey&&a===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&a===last){e.preventDefault();first.focus();}});
function openModal(html,cls=''){ovRemember();const o=$('#ov');if(o)o.remove();const ov=document.createElement('div');ov.className='ov';ov.id='ov';ov.innerHTML=`<div class="modal ${cls}" role="dialog" aria-modal="true" tabindex="-1">${html}</div>`;ov.addEventListener('mousedown',e=>{if(e.target===ov)closeModal();});document.body.appendChild(ov);fixText(ov);mountTrails(ov);{const t=ov.querySelector('.md-h h3,.md-h h2,h2,h3');if(t){t.id=t.id||'ov-titre-'+Math.random().toString(36).slice(2,8);ov.firstElementChild.setAttribute('aria-labelledby',t.id);}}try{ov.firstElementChild.focus({preventScroll:true});}catch(e){}setTimeout(()=>{const i=ov.querySelector('[autofocus]'),a=document.activeElement;if(i&&!(a&&a!==i&&ov.contains(a)&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName)))i.focus();},60);}   /* le curseur va au champ prévu, sauf si le joueur en a déjà choisi un autre dans la fenêtre */
function closeModal(){const o=$('#ov');if(o)o.remove();S.ui.sheet=null;}
/* C18 : une condition remplie s'écrit « 60 / 60 ✓ » (et non « 186 sur 60 ») ; noBtn retire le bouton de la ligne quand il ferait doublon */
function condH(c,noBtn){const val=c.ok?(c.k==='acc'?_t('{0} % · {1} % requis',[c.have,c.need]):c.k==='xp'?_t('{0} / {1}',[F.int(c.need),F.xp(c.need)]):c.k==='top'?_t('{0}, dans le top {1}',[F.ord(c.have),c.need]):_t('{0} / {1}',[F.int(c.need),F.int(c.need)]))
  :c.k==='acc'?`${_t("{0} % sur {1} % requis",[c.have,c.need])}`:c.k==='xp'?`${_t("{0} sur {1}",[F.int(c.have),F.xp(c.need)])}`:c.k==='top'?`${_t("{0}e, il faut être dans le top {1}",[F.int(c.have),c.need])}`:`${_t("{0} sur {1}",[F.int(c.have),F.int(c.need)])}`;const pct=c.rev?(c.ok?100:Math.min(100,c.need/c.have*100)):Math.min(100,c.have/Math.max(1,c.need)*100);
 return `<div class="cond${c.ok?' ok':''}"><span class="ck"${c.ok?` role="img" aria-label="${_t('Fait')}"`:''}>${c.ok?ic('check',13,'#fff',3):ic('lock',12,'#7A808C',2.2)}</span><div><div class="cl">${c.label}</div><div class="cv">${val}</div>${c.ok?'':`<div class="cv">${CHINT[c.k]}</div><div class="xpbar sm"><i style="width:${pct}%"></i></div>`}</div>${c.ok||noBtn?'':`<a class="btn b-ghost sm" href="${CGO[c.k][0]}" data-a="close">${CGO[c.k][1]}</a>`}</div>`;}
function bestGo(L){const c=L.find(x=>!x.ok);return c?CGO[c.k]:['#eclair',_t("Gagner de l’XP")];}
/* aperçu de ce que le rang débloque, tiré du contenu existant, flouté et inerte : il ne débloque rien */
const vipFake=()=>[['satoshi',_t("Je sors de #btc150k à 64, merci pour le voyage.")],['lea',_t("Gros flux sur #clasico, je vous partage ma lecture.")],['kaizen',_t("La BCE va surprendre, je reste sur #bce.")],['maxou',_t("Qui est sur la manche éclair de 22 h ?")]];
function lockPrevH(g){const h=g==='stats'?statsLinesH(curMarket()||MK.btc150k):g==='vip'?vipFake().slice(0,3).map(([u,t])=>msgH(mkMsg({u,k:'msg',text:t,r:{}}))).join(''):'';
 return h?`<div class="lk-prev" aria-hidden="true" inert><div class="lk-blur">${h}</div><span class="lk-chip">${ic('lock',11)} ${_t('Aperçu')}</span></div>`:'';}
function lockModal(g){const G=GATES[g],t=G.t,r=myRank(),L=conds(t),bg=bestGo(L),seen=new Set([bg[1]]);const rows=L.map(c=>{const lb=CGO[c.k][1],dup=!c.ok&&seen.has(lb);if(!c.ok)seen.add(lb);return condH(c,dup);}).join('');openModal(`<div class="md lockm"><button class="x" data-a="close" aria-label="${_t("Fermer")}" style="align-self:flex-end;margin-bottom:-30px">${ic('x')}</button>${emb(t,0,'xl')}<div><h3 style="font-size:22px;font-weight:700;letter-spacing:-.01em">${G.label}</h3><p class="muted mt-2">${_t("Se débloque au rang")} <b class="c-1">${TIERS[t].name}</b>${_t(". Tu es {0}. Voici ce qu’il te manque :",[rankName(r.t,r.d)])}</p></div>${lockPrevH(g)}<div class="conds-l">${rows}</div><div class="md-acts w-full"><a class="btn b-ink lg full" href="${bg[0]}" data-a="close">${bg[1]}</a><a class="link lk-more" href="#rang" data-a="close">${_t("Voir mon rang en détail")}</a></div></div>`);}
function tierModal(t){const r=myRank(),T=TIERS[t],L=conds(t),feats=FEATURES.filter(f=>f.t===t);const status=t<r.t?_t("Rang déjà atteint"):t===r.t?`${_t("Tu es {0}",[rankName(r.t,r.d)])}`:(L.every(c=>c.ok)?_t("Conditions remplies"):_t("Pas encore débloqué"));
 openModal(`<div class="md"><div class="md-h"><div class="row-c gap-4">${emb(t,t===r.t?r.d:(t<r.t?2:0),'lg')}<div><h3 class="t-5">${T.name}</h3><p>${status}</p></div></div><button class="x" data-a="close" aria-label="${_t("Fermer")}">${ic('x')}</button></div>
 <div><div class="h2 t-3 mb-2">${_t("Divisions")}</div><div class="conds4" style="grid-template-columns:repeat(${DIV_XP[t].length},minmax(0,1fr))">${DIV_XP[t].map((x,i)=>`<div class="pn" style="padding:12px;border-radius:12px${t===r.t&&i===r.d?';background:var(--ouiS);border-color:var(--oui)':''}"><small>${rankName(t,i)}</small><b class="num t-4">${F.xp(x)}</b></div>`).join('')}</div></div>
 <div><div class="h2 t-3">${_t("Conditions pour entrer")}</div>${L.map(condH).join('')}</div>
 <div><div class="h2 t-3 mb-1">${_t("Ce que ce rang débloque")}</div>${feats.map(f=>`<div class="perk"><span class="pi">${ic(f.ic,16)}</span>${f.label}</div>`).join('')}</div>
 <a class="btn b-ink lg full" href="#rang" data-a="close">${_t("Voir ma progression")}</a></div>`,'wide');}

/* ===================== Ticket de pari ===================== */
const tState=ctx=>ctx==='sheet'?S.ui.sheet:S.ui.ticket;
function calcT(st){if(st.otype==='limit')return calcLimit(st);const m=MK[st.m],r=myRank(),disc=r.t>=5,v=Math.max(0,F.parse(st.amt));
 if(st.mode==='sell'){const p=posOf(st.m,st.side),q=quoteSell(m,st.side,Math.min(v,p.sh));return {sell:true,q,price:q.avg,sh:q.sh,pro:q.pro,pnl:q.pro-q.sh*p.avg/100,impact:q.impact,full:q.full,ok:q.sh>0&&q.full};}
 const q=quoteBuy(m,st.side,v,disc);
 return {q,price:q.avg,amt:v,fee:q.fee,fr:q.feeRate,theta:q.theta,sh:q.sh,gain:q.gain,impact:q.impact,pm:q.pm,full:q.full,maxTotal:q.maxTotal,insuf:v>S.me.balance+1e-9,ok:v>=1&&v<=S.me.balance+1e-9&&q.full&&q.sh>0};}
function ticketInner(ctx){const st=tState(ctx),m=MK[st.m],mine=S.me.positions.filter(p=>p.m===m.id),sell=st.mode==='sell';let h='';
 if(ctx==='page')h+=`<div class="tabs"><button class="${!sell?'on':''}" data-a="tmode" data-v="buy">${_t("Acheter")}</button><button class="${sell?'on':''}" data-a="tmode" data-v="sell">${_t("Vendre")}</button></div>`;
 if(sell&&!mine.length)return h+`<div class="empty p-6-2">${_t("Tu n’as pas encore de parts sur ce marché.<br>")}<button class="btn b-ink sm mt-3" data-a="tmode" data-v="buy">${_t("Acheter des parts")}</button></div>`;
 const allowed=sell?mine.map(p=>p.s):['oui','non'];if(!allowed.includes(st.side))st.side=allowed[0];
 h+=`<div class="sides">${['oui','non'].map(s=>{const dis=!allowed.includes(s);return `<button class="sd ${s}${st.side===s?' on':''}${dis?' op-35':''}" data-a="tside" data-v="${s}" data-ctx="${ctx}"${dis?' disabled':''}>${mxH(m.id,s,m.p)}<span>${s==='oui'?_t("Oui"):_t("Non")}</span><b class="num" data-${s==='oui'?'mc':'mcn'}="${m.id}">${F.c(s==='oui'?m.p:100-m.p)}</b></button>`;}).join('')}</div>${otypeH(ctx,st)}${st.otype==='limit'?lpFieldH(ctx,st):''}
 <div class="amt-h"><b>${sell?_t("Parts à vendre"):_t("Montant")}</b><span>${sell?`${_t("Tu as {0} parts",[F.d1(posOf(m.id,st.side).sh)])}`:S.me.logged?`${_t("Solde")} <span data-bal-plain>${F.bal(S.me.balance,true)}</span>`:`<a class="link" href="#connexion">${_t("Se connecter")}</a>`}</span></div>
 <label class="amt"><input data-tamt="${ctx}" inputmode="decimal" value="${esc(st.amt)}" aria-label="${sell?_t("Parts à vendre"):_t("Montant en dollars")}"><span>${sell?_t('parts'):'$'}</span></label>
 <div class="presets">${(sell?[[F.pct(25),.25],[F.pct(50),.5],[F.pct(75),.75],[_t('Tout'),1]]:[[bidi('+'+plain(F.usd0(10))),10],[bidi('+'+plain(F.usd0(50))),50],[bidi('+'+plain(F.usd0(100))),100],[_t('Max'),'max']]).map(([l,v])=>`<button class="btn b-ghost sm" data-a="preset" data-v="${v}" data-ctx="${ctx}">${l}</button>`).join('')}</div>
 <div class="col gap-4" data-tcalc="${ctx}">${calcH(ctx)}</div>`;return h;}
function tNotesH(c){let h='';
 if(!c.full&&c.amt>0)h+=`<div class="limit over"><span>${_t("Pas assez de liquidité sur ce marché : ton ordre est limité à {0}.",[F.usd0(c.maxTotal)])}</span></div>`;
 else if(c.impact>=1)h+=`<p class="note warn">${_t("Ordre important : ton achat fait monter le prix de {0} pts. Ton prix moyen sera meilleur si tu répartis ta mise.",[F.d1(c.impact)])}</p>`;
 return h;}
function calcH(ctx){const st=tState(ctx),c=calcT(st),r=myRank(),Side=st.side==='oui'?_t("Oui"):_t("Non");
 if(c.limit)return limitCalcH(ctx,c);
 if(c.sell)return sellCalcH(ctx,c);
 const nt=r.t<8?r.t+1:null;
 /* L'essentiel d'abord : le gain et le bouton. Le reste (prix, parts, impact, frais, combiné…) se déplie. */
 return `<div class="calc"><div class="line gain"><span>${_t("Gain si {0}",[Side])}</span><b data-c="gain">${c.ok?F.signed(Math.max(0,c.gain)):'—'}</b></div></div>
 <div class="tnotes" data-c="notes">${tNotesH(c)}</div>
 ${can('share')?`<label class="chk"><input type="checkbox" data-announce="${ctx}"${st.announce?' checked':''}> ${_t("Annoncer ma mise dans le chat du marché")} <span class="xpc">${bidi('+5 XP')}</span></label>`:''}
 <div class="tbuy">${c.insuf?`<a class="btn b-pri lg full" href="#depot" data-a="close">${_t("Solde insuffisant : déposer des fonds")}</a>`:`<button class="btn ${st.side==='oui'?'b-yes':'b-no'} lg full" data-a="buy" data-ctx="${ctx}"${c.ok?'':' disabled'} data-c="btn">${_t("Acheter {0} pour {1}",[Side,F.usd(c.amt)])}</button>`}</div>
 <details class="tdet"><summary>${_t("Détail du pari")}</summary><div class="calc"><div class="line"><span>${_t("Prix moyen")}</span><b data-c="price">${F.c1(c.price)}</b></div><div class="line"><span>${_t("Parts obtenues")}</span><b data-c="sh">${F.d2(Math.max(0,c.sh))}</b></div><div class="line"><span>${_t("Impact sur le prix")}</span><b data-c="imp">${F.imp(c.impact)}</b></div><div class="line"><span>${_t("Frais (")}<span data-c="frp">${F.pct1(c.fr)}</span>)</span><span class="row-c">${r.t<5?`<button class="lk" data-a="lock" data-g="fees">${_t("{0} −10 % dès Diamant",[ic('lock',10)])}</button>`:''}<b data-c="fee">${F.usd(c.fee)}</b></span></div>${typeof clanTicketH==='function'?clanTicketH(st.m,c.amt):''}<div class="line"><span>${_t("Ordre max sur ce marché :")}</span><b data-c="maxl">${F.usd0(c.maxTotal)}</b></div></div>
 ${typeof slipCan==='function'?`<button class="btn b-ghost sm full cb-addbtn" data-a="cb-add" data-m="${st.m}" data-s="${st.side}" data-ctx="${ctx}">${_t("{0} Ajouter au combiné{1}",[ic('layers',14),slip().legs.length?` <span class="xpc">${slip().legs.length}</span>`:''])}</button>`:''}
 <p class="note">${_t("Chaque part gagnante rapporte 1 $, payé par ceux qui ont pris l’autre côté. +10 XP par pari. Revendre avant la clôture est gratuit.")}</p></details>`;}
function updTicket(ctx){const el=$(`[data-tcalc="${ctx}"]`);if(el){const d=el.querySelector('details.tdet'),ouvert=d&&d.open;el.innerHTML=calcH(ctx);fixText(el);if(ouvert){const n=el.querySelector('details.tdet');if(n)n.open=true;}}}   /* le détail déplié le reste pendant la saisie */
function updNums(ctx){const box=$(`[data-tcalc="${ctx}"]`);if(!box)return;const st=tState(ctx),c=calcT(st);if(c.limit){updTicket(ctx);return;}const set=(k,v)=>{const e=box.querySelector(`[data-c="${k}"]`);if(e&&e.textContent!==v)e.textContent=v;};set('price',F.c1(c.price));
 if(c.sell){set('pro',F.usd(c.pro));set('imp',F.imp(-c.impact));sellSync(box,c);}else{set('sh',F.d2(Math.max(0,c.sh)));set('imp',F.imp(c.impact));set('fee',F.usd(c.fee));set('frp',F.pct1(c.fr));set('gain',c.ok?F.signed(Math.max(0,c.gain)):'—');set('maxl',F.usd0(c.maxTotal));{const cl=box.querySelector('[data-c="clan"]');if(cl){const ch=clanTicketIn(st.m,c.amt);if(cl._h!==ch){cl._h=ch;cl.innerHTML=ch;}}}
  const n=box.querySelector('[data-c="notes"]');if(n){const nh=tNotesH(c);if(n.dataset.h!==nh){n.dataset.h=nh;n.innerHTML=nh;}}
  const b=box.querySelector('button[data-c="btn"]');if(b)b.disabled=!c.ok;}}
function rerenderTicket(){const t=$('[data-ticket="page"]');if(t){t.innerHTML=ticketInner('page');fixText(t);}const pb=$('[data-posbox]');if(pb){pb.outerHTML=posBoxH(MK[S.ui.ticket.m]);const n=$('[data-posbox]');fixText(n);}const ob=$('[data-ordbox]');if(ob){ob.outerHTML=ordersBoxH(MK[S.ui.ticket.m]);const n2=$('[data-ordbox]');if(n2)fixText(n2);}}
function openBet(mid,side,amt,opt={}){const m=MK[mid];closeModal();S.ui.sheet={m:mid,side,mode:'buy',amt:String(amt||25),announce:true,followOf:opt.followOf||null};
 openModal(`<div class="md"><div class="md-h"><div><p>${_t(m.cat)}${opt.followUser?`${_t(", tu suis la mise de {0}",[esc(userOf(opt.followUser).n)])}`:''}</p><h3>${esc(m.q)}</h3></div><button class="x" data-a="close" aria-label="${_t("Fermer")}">${ic('x')}</button></div><div class="ticket no-shadow" data-ticket="sheet">${ticketInner('sheet')}</div><a class="link t-2 ta-c" href="#marche-${mid}" data-a="close">${_t("Voir le marché et son chat")}</a></div>`,'wide');}
/* Parier se fait en trois temps : 1. validation et aperçu (calcT) ; 2. écriture comptable — ici en mode local, par le
   serveur en mode serveur (srvAcheter) ; 3. effets d'interface, les mêmes dans les deux modes (betEffets). */
function placeBet(ctx,ev){const st=tState(ctx),m=MK[st.m],c=calcT(st);if(!c.ok)return;if(typeof rgBlocked==='function'&&rgBlocked('bet'))return;
 if(SRV()){srvAcheter(ctx,ev,st,m,c);return;}
 const before=myRank();
 S.me.balance-=c.amt;const p=S.me.positions.find(x=>x.m===m.id&&x.s===st.side);if(p){p.avg=(p.avg*p.sh+c.price*c.sh)/(p.sh+c.sh);p.sh+=c.sh;}else S.me.positions.push({m:m.id,s:st.side,sh:c.sh,avg:c.price});
 S.me.played++;S.me.maxBet=Math.max(S.me.maxBet,c.amt);S.me.realized-=c.fee;if(typeof copierFees==='function')copierFees(c.amt,c.fr);
 const old=m.p;applyBuy(m,c.q);m.anchor=clamp(m.anchor+c.q.impact*(st.side==='oui'?1:-1)*.7,5,95);m.people++;addBet(m,{s:st.side==='oui'?1:0,a:Math.min(1,c.amt/300),me:1});updateMarket(m,old);
 betEffets(ctx,ev,st,m,c,before);}
function betEffets(ctx,ev,st,m,c,before){
 updateHeader();gainXP(10,ev);mission('bet');
 if(SRV()){if(st.followOf)srvSuivreMise(st.followOf);if(st.announce&&can('share'))srvPartagerMise('m:'+m.id,m.id,st.side,true);}   /* mode Compte : suivi et annonce tenus par le serveur */
 if(!SRV()){
 if(st.followOf){const x=MSG[st.followOf];if(x){x.followers++;setFc(x);setTimeout(()=>gainXP(5),550);}}
 if(st.announce&&can('share')){const x=mkMsg({u:'me',k:'bet',text:'',bet:{m:m.id,s:st.side,amt:Math.round(c.amt),price:Math.round(c.price)}});addMsg('m:'+m.id,x);setTimeout(()=>gainXP(5),800);scheduleFollowers(x,'m:'+m.id);}
 }
 toast({tone:'blue',icon:'check',title:_t("Pari placé"),text:`${_t("{0} parts {1} sur {2}",[F.d2(c.sh),st.side==='oui'?_t("Oui"):_t("Non"),m.short])}`,sub:typeof clanToastTxt==='function'?clanToastTxt(clanCount(m.id,c.amt)):'',href:'#marche-'+m.id});
 notif('check',`${_t("Pari placé : {0} sur {1}, {2}.",[F.usd(c.amt),st.side==='oui'?_t("Oui"):_t("Non"),m.short])}`,'#profil');checkBadges();if(before)checkRank(before);save();
 if(ctx==='sheet')closeModal();else rerenderTicket();}
function scheduleFollowers(x,rid){const n=1+Math.floor(R()*3),ep=S.epoch;for(let i=0;i<n;i++)setTimeout(()=>{if(ep!==S.epoch)return;const u=pickUser(),before=myRank();x.followers++;setFc(x);S.me.followed++;addMsg(rid,mkMsg({k:'evt',text:`${_t("{0} a suivi ta mise",[userOf(u).n])}`}));toast({icon:'users',title:`${_t("{0} a suivi ta mise",[userOf(u).n])}`,text:'+20 XP',href:rid.startsWith('m:')?'#marche-'+rid.slice(2):'#chat'});gainXP(20);checkRank(before);checkBadges();save();},4000+i*5200+R()*3500);}
/* Vendre : même découpage que parier. */
function sellPos(ctx){const st=tState(ctx),c=calcT(st);if(!c.ok)return;if(SRV()){srvVendre(ctx,st,c);return;}const p=posOf(st.m,st.side);p.sh-=c.sh;S.me.balance+=c.pro;S.me.realized+=c.pnl;if(p.sh<.05){S.me.positions=S.me.positions.filter(x=>x!==p);if(typeof dropGuard==='function')dropGuard(st.m,st.side);}S.me.history.unshift({k:'sell',m:st.m,q:MK[st.m].q,s:st.side,win:c.pnl>=0,pnl:c.pnl,at:now()});
 const m=MK[st.m],old=m.p;applySell(m,c.q);addBet(m,{s:st.side==='oui'?0:1,a:Math.min(1,c.pro/300),me:1});updateMarket(m,old);
 sellEffets(st,c);}
function sellEffets(st,c){
 updateHeader();toast({tone:c.pnl>0.004?'green':c.pnl<-0.004?'red':'',icon:'check',title:c.pnl>0.004?`${_t("Vendu avec {0} de gain",[F.signed(c.pnl)])}`:c.pnl<-0.004?`${_t("Vendu avec {0} de perte",[F.signed(c.pnl)])}`:_t("Vendu au prix d’achat"),text:`${_t("{0} crédités sur ton solde",[F.usd(c.pro)])}`});st.amt='';rerenderTicket();save();}

/* ===================== Accueil ===================== */
const SORTS={actifs:(a,b)=>b.heat*Math.log(b.vol)-a.heat*Math.log(a.vol),variation:(a,b)=>Math.abs(b.p-b.d0)-Math.abs(a.p-a.d0),cloture:(a,b)=>a.days-b.days,volume:(a,b)=>b.vol-a.vol};
function heroH(m){return `<section class="pn pad hero"><div class="hrow"><span class="kick"><i class="live"></i>${_t("Le marché qui bouge le plus en ce moment")}</span><span class="ppl">${ic('users',16)}<span><b data-people="${m.id}">${F.int(m.people)}</b> ${_t("participants")}</span></span></div>
 <div class="hmain"><a class="hq" href="#marche-${m.id}">${qNw(m.q)}</a><div class="hp"><div class="num" data-mp="${m.id}">${F.pct(m.p)}</div><div class="delta up" data-md="${m.id}" data-long="${_t("sur 24 heures")}">${ptsLong(m.p-m.d0,_t('sur 24 heures'))}</div></div></div>
 <div class="trail big" data-trail="${m.id}"></div><div class="tlegend"><span>${_t("Plus anciennes")}</span><span>${_t("Maintenant")}</span></div>
 <div class="hfoot"><div class="hbtns"><button class="btn b-yes lg" data-a="bet" data-m="${m.id}" data-s="oui">${mxH(m.id,'oui',m.p)}${buyLbl(m.id,'oui',m.p)}</button><button class="btn b-no lg" data-a="bet" data-m="${m.id}" data-s="non">${mxH(m.id,'non',m.p)}${buyLbl(m.id,'non',100-m.p)}</button></div><div class="kvs"><div class="kv"><small>${_t("Volume")}</small><b class="num" data-mv="${m.id}">${F.compact(m.vol)}</b></div><div class="kv"><small>${_t("Clôture")}</small><b class="num">${m.close}</b></div><a class="kv" href="#marche-${m.id}"><small>${_t("Messages")}</small><b class="num" data-mmsg="${m.id}">${F.int(m.msgs)}</b></a></div></div></section>`;}
/* badge « ×1,75 » : ce que rapporte 1 $ misé sur ce côté (100 / prix) */
/* C9 : un seul libellé d'achat partout, « Acheter Oui 63 ¢ », avec des espaces simples. Dans les boutons étroits
   (lignes de la liste), le verbe n'est pas affiché mais reste lu par les lecteurs d'écran. */
const buyLbl=(id,s,p)=>`<span class="buyl"><span class="bv">${_tc('Acheter','verbe')} </span>${s==='oui'?_t('Oui'):_t('Non')} <span data-${s==='oui'?'mc':'mcn'}="${id}">${F.c(p)}</span></span>`;
const mxH=(id,s,p)=>`<i class="mx" data-mx="${id}" data-side="${s}">${F.mult(s==='oui'?p:100-p)}</i>`;
/* bouton de suivi : un seul libellé, à toutes les largeurs */
const watchTxt=on=>on?_t('Suivi'):_t('Suivre');
/* titres de marché : un mot comme « dépassera-t-il » ne se coupe pas au trait d'union (le texte lui-même ne change pas) */
const qNw=q=>esc(q).replace(/\S+-t-\S+/g,w=>'<span class="nw">'+w+'</span>');
/* Ordinateur (880 px et plus) ou téléphone : décide de la place de certains blocs dans la page (carte Éclair de l'accueil). */
const GRAND=()=>matchMedia('(min-width:880px)').matches;
/* Image d'un marché : carrée, coins arrondis, à gauche de la question, d'une seule taille par contexte (réglée en CSS).
   Sans image : l'icône de la catégorie sur fond gris neutre. Les images réelles arrivent avec les marchés réels (partie D). */
const CAT_IC={'Crypto':'coins','Football':'trophy','Sport':'trophy','Politique':'bank','Tech et IA':'cpu','Tech':'cpu','Économie':'percent','Bourse':'chart','Culture':'film','Jeux vidéo et culture':'film','Météo':'cloud'};
function mImgH(m){const src=m&&m.img||'';return `<span class="mimg" aria-hidden="true">${src?`<img src="${esc(src)}" alt="" loading="lazy" decoding="async">`:ic(CAT_IC[m&&m.cat]||'target',18)}</span>`;}
function rowH(m){const d=m.p-m.d0;return `<div class="row${m.hotUntil>now()?' hot':''}" data-href="#marche-${m.id}" data-row="${m.id}">${mImgH(m)}<div class="qcell"><div class="cat" data-hot="${_t('Ça chauffe')}">${_t(m.cat)}${m.creator==='me'?`<span class="ctag">${_t("Créé par toi")}</span>`:''}</div><a class="q" href="#marche-${m.id}">${qNw(m.q)}</a></div><div class="pv"><div class="num" data-mp="${m.id}">${F.pct(m.p)}</div><div class="delta ${d>=0?'up':'dn'}" data-md="${m.id}">${F.pts(d)}</div></div><div class="tr"><div class="trail" data-trail="${m.id}"></div></div><div class="vol"><div class="v" data-mv="${m.id}">${F.compact(m.vol)}</div><div class="c">${m.close}</div></div><div class="acts"><button class="btn b-yes-soft sm" data-a="bet" data-m="${m.id}" data-s="oui">${mxH(m.id,'oui',m.p)}${buyLbl(m.id,'oui',m.p)}</button><button class="btn b-no-soft sm" data-a="bet" data-m="${m.id}" data-s="non">${mxH(m.id,'non',m.p)}${buyLbl(m.id,'non',100-m.p)}</button></div></div>`;}
function boardH(){if(S.ui.cat==='Mes paris créés')return myBoardH();const inCat=m=>S.ui.cat==='Tout'||(S.ui.cat==='Pour toi'?S.me.interests.includes(m.cat):m.cat===S.ui.cat);const L=MARKETS.filter(m=>!m.parent&&inCat(m)).concat(GROUPS.filter(inCat).map(groupProxy)).sort((a,b)=>((b.creator==='me')-(a.creator==='me'))||SORTS[S.ui.sort](a,b));if(!L.length)return `<div class="empty">${_t("Aucun marché dans cette catégorie pour l’instant.")} <button class="link" data-a="cat" data-v="Tout">${_t("Voir tous les marchés")}</button></div>`;return `<div class="bd-cap">${_t("Variations sur 24 heures")}</div><div class="hd"><span>${_t("Marché")}</span><span>${_t("Chance Oui")}<small class="hd-s">${_t("variation sur 24 h")}</small></span><span>${S.ui.tmode==='bars'?_t("Mises en direct"):_t("Tendance")}</span><span>${_t("Volume")}</span><span></span></div>`+L.map(x=>x.group?groupRowH(x.group):rowH(x)).join('');}
function homeChatH(){const rid=S.ui.homeRoom;room(rid).unread=0;return chatH(rid,'home',`<div class="chat-h"><div class="tt"><h2><i class="rdot" aria-hidden="true"></i>${_t("Live chat")}</h2><span class="on-c"><i class="live"></i><span><span data-online>${F.int(S.online)}</span> ${_t("connectés")}</span></span></div><div class="roomtabs tabs">${['general','m:btc150k','m:clasico'].map(r=>`<button class="${rid===r?'on':''}" data-a="hroom" data-room="${r}">${esc(roomLabel(r))}<span data-unread="${r}">${rid===r?'':unr(r)}</span></button>`).join('')}<button data-a="${can('vip')?'troom':'lock'}" data-g="vip" data-room="vip">${_t("{0}Salon VIP",[can('vip')?'':ic('lock',13)])}</button></div></div>`);}
/* Accueil. Visiteur : présentation et marché phare côte à côte (introH, js/refonte.js). Ordinateur : la carte Éclair
   rejoint la colonne latérale, qui reste visible au défilement ; sur téléphone, elle reste sous le marché phare. */
function vHome(){const vis=!S.me.logged,grand=GRAND(),vedette=heroH(MK.btc150k);
 return `<div class="wrap"><h1 class="vhid">${_t("Marchés")}</h1><div class="g-home"><div class="col">${vis&&typeof introH==='function'?introH(vedette):vedette}${grand?'':flashTeaserH()}
 <div class="filters"><div class="tabs">${homeTabs().map(c=>`<button class="${S.ui.cat===c?'on':''}" data-a="cat" data-v="${c}">${_t(c)}</button>`).join('')}</div><div class="fright">${tmodeH()}<label class="sort"><span class="sort-l">${_t("Trier par")}</span> <select data-sort aria-label="${_t("Trier les marchés")}">${[['actifs',_t("Les plus actifs")],['variation',_t("Plus forte variation")],['cloture',_t("Clôture proche")],['volume',_t("Plus gros volume")]].map(([v,l])=>`<option value="${v}"${S.ui.sort===v?' selected':''}>${l}</option>`).join('')}</select></label>${gateBtn('propose',ic('plus',15,can('propose')?'#fff':'currentColor')+_t(" Créer un pari"),(can('propose')?'b-ink sm':'b-white sm')+' f-new')}</div></div>
 <section class="pn board" id="board">${boardH()}</section>
 <div class="f-new-m">${gateBtn('propose',ic('plus',16)+_t(" Créer un pari"),'b-white full')}</div>
 </div><aside class="col home-side rail-fixe">${grand?flashTeaserH():''}${bigsBlocH()}</aside></div></div>`;}

/* ===================== Marché ===================== */
const XLAB={'1 h':['−60 min','−45 min','−30 min','−15 min',_t("Maintenant")],'6 h':['−6 h','−4 h 30','−3 h','−1 h 30',_t("Maintenant")],'1 j':['00:00','06:00','12:00','18:00',_t("Maintenant")],'1 sem.':[_t("Lun."),_t("Mer."),_t("Ven."),_t("Dim."),_t("Maintenant")],'Tout':[_t("Juin"),_t("Août"),_t("Sept."),_t("Oct."),_t("Maintenant")]};
function series(m,tf){const n=72,r=rng(hash(m.id+tf));const st={'1 h':m.p-1.5+r()*3,'6 h':m.p-(m.p-m.d0)*.45,'1 j':m.d0,'1 sem.':m.d0-5+r()*10,'Tout':50}[tf];let w=0;const out=[];for(let i=0;i<n;i++){const f=i/(n-1);w+=(r()-.5)*2.4;out.push(clamp(st+(m.p-st)*f+w*(1-f)*.9,2,98));}out[n-1]=m.p;return out;}
function mktChatHead(m){return `<div class="chat-h pb-4"><div class="tt"><div><h2>${_t("Live chat du marché")}</h2><div class="sub"><span data-monline="${m.id}">${F.int(m.online)}</span> ${_t("personnes dans ce chat,")} <span data-mmsg="${m.id}">${F.int(m.msgs)}</span> ${_t("messages")}</div></div><div class="seg"><button class="${S.ui.mtab==='live'?'on':''}" data-a="mtab" data-v="live">${_t("En direct")}</button><button class="${S.ui.mtab==='top'?'on':''}" data-a="mtab" data-v="top">${_t("Les plus utiles")}</button></div></div></div>`;}
function posBoxH(m){const L=S.me.positions.filter(p=>p.m===m.id);if(!L.length)return `<div data-posbox="${m.id}"></div>`;return `<section class="pn pad" data-posbox="${m.id}"><div class="h2">${_t("Ta position")}</div>${L.map(p=>{const k=m.id+'-'+p.s,v=posPnl(p);return `<div class="prow"><div class="pl"><span class="sidechip ${p.s}">${p.s==='oui'?_t("Oui"):_t("Non")}</span><div><div class="nm">${_t("{0} parts{1}",[F.d1(p.sh),guardTagH(p)])}</div><div class="sub">${_t("Prix moyen {0}",[F.c(p.avg)])}</div></div></div><div class="pr"><b class="num" data-pv="${k}">${F.usd(posValue(p))}</b><small class="${plc(v)}" data-ppnl="${k}">${F.signed(v)}</small></div>${shareBtnH('bet',{m:m.id,s:p.s})}</div>`;}).join('')}${sellBtnH(m.id)}${guardBtnH(m.id)}</section>`;}
function radiantsH(m,issue){const sh=clamp(Math.round(m.p+(hash(m.id)%13)-5),6,94);   /* issue : nom (déjà échappé) de l'issue concernée, sur la page d'un marché à plusieurs issues */const top=['satoshi','lea','kaizen'].map((u,i)=>{const r=rng(hash(u+m.id));const s=i<2?(sh>=50?'oui':'non'):(sh>=50?'non':'oui');return {u,s,amt:Math.round(300+r()*4200)};});
 return `<section class="pn pad"><div class="h2">${_t("Ce que font les Radiants")}</div><div class="sub">${issue?_t("Les 100 meilleurs joueurs de la saison, sur « {0} »",[issue]):_t("Les 100 meilleurs joueurs de la saison")}</div><div class="split mt-4 mb-2"><i data-rsplit="${m.id}" style="width:${sh}%"></i></div><div class="line pt-0"><b class="up">${_t("{0} % sur Oui",[sh])}</b><b class="dn">${_t("{0} % sur Non",[100-sh])}</b></div><hr class="mt-3 mb-1">${top.map(t=>`<a class="prow" href="#joueur-${t.u}"><span class="pl">${avH(t.u,36,'span')}<span><span class="nm d-block">${esc(userOf(t.u).n)}</span>${rk(userOf(t.u).t,userOf(t.u).d)}</span></span><span class="pr"><b class="num ${t.s==='oui'?'up':'dn'}">${F.usd0(t.amt)}</b><small>${_t("sur {0}",[t.s==='oui'?_t("Oui"):_t("Non")])}</small></span></a>`).join('')}<button class="lockrow mt-3 w-full" data-a="lock" data-g="opinion"><span class="row-c gap-3">${ic('eye',16,'#7A808C')}<span class="t-2 ta-s">${_t("Ton avis s’affichera ici quand tu seras Radiant.")}</span></span>${rk(8,0)}</button></section>`;}
function vMarket(id){const m=MK[id];if(!m)return vHome();if(S.ui.ticket.m!==id){S.ui.ticket={m:id,side:'oui',mode:'buy',amt:'50',announce:true};}const rid='m:'+id;room(rid).unread=0;
 return `<div class="wrap"><div class="mtop"><div><nav class="crumbs"><a href="#accueil">${_t("Marchés")}</a><span>/</span><a href="#accueil" data-a="cat" data-v="${m.cat}">${_t(m.cat)}</a>${m.parent?`<span>/</span><a href="#marche-${m.parent}">${esc(GK[m.parent].short)}</a>`:''}</nav><div class="mq-t">${mImgH(m)}<h1 class="mq">${qNw(m.q)}</h1></div><div class="mmeta">${m.parent?`<span class="ctag multi">${_t("{0} issues",[GK[m.parent].outcomes.length])}</span>`:''}${m.creator==='me'?`<span class="ctag">${_t("Créé par toi")}</span>`:''}<span>${_t("Clôture : <b>{0}</b>",[m.closeLong])}</span><span>${_t("Volume")} <b data-mv="${id}">${F.compact(m.vol)}</b></span><span title="${_t("Argent disponible dans le carnet à ±10 ¢ du prix")}">${_t("Liquidité")} <b data-liq="${id}">${F.compact(bookDepth(m)*10)}</b></span><span><b data-people="${id}">${F.int(m.people)}</b> ${_t("participants")}</span><span><b data-mmsg="${id}">${F.int(m.msgs)}</b> ${_t("messages dans le chat")}</span></div></div><div class="mact"><button class="btn b-white" data-a="duel-open" data-m="${id}">${_t("{0} Défier",[ic('swords',16)])}</button><button class="btn b-white" data-a="copylink" data-v="#marche-${id}">${_t("{0} Partager",[ic('share',16)])}</button><button class="btn b-white" data-a="watch" data-m="${id}" aria-pressed="${S.me.watch.includes(id)}">${ic('star',16)} <span data-watch="${id}">${watchTxt(S.me.watch.includes(id))}</span></button></div></div>
 <div class="g-mkt"><section class="pn pad a-chart"><div class="cp-h"><div class="cp-p"><b class="num" data-mp="${id}">${F.pct(m.p)}</b><div><div class="cpt">${_t("de chances que ce soit Oui")}</div><div class="delta ${perDelta(m)>=0?'up':'dn'}" data-mdp="${id}">${ptsLong(perDelta(m),perLab())}</div></div></div><div class="row-c flex-wrap"><div class="seg">${Object.keys(XLAB).map(t=>`<button class="${S.ui.tf===t?'on':''}" data-a="tf" data-v="${t}">${_t(t)}</button>`).join('')}</div>${gateBtn('stats',ic('chart',15)+_t(" Stats avancées"),'b-ghost sm')}</div></div>
 ${chartToolsH(id)}<div class="chart" data-chart="${id}">${chartInner(m)}</div><div class="xax">${xlabs(S.ui.tf).map(s=>`<span>${s}</span>`).join('')}</div>
 <details class="tdet trdet"><summary>${S.ui.tmode==='bars'?_t("Mises en direct"):_t("Évolution en direct")}</summary><div class="trh">${tmodeH()}${S.ui.tmode==='bars'?`<span class="legend"><span><i class="sw-o"></i>${_t('Oui')}</span><span><i class="sw-n"></i>${_t('Non')}</span><span><i class="sw-me"></i>${_t('Toi')}</span></span>`:''}</div><div class="trail mid" data-trail="${id}"></div></details></section>
 <aside class="col a-side"><section class="pn pad ticket" data-ticket="page">${ticketInner('page')}</section>${posBoxH(m)}${ordersBoxH(m)}${radiantsH(m)}</aside>
 ${chatH(rid,'mkt a-chat',mktChatHead(m))}
 <section class="pn pad a-rules"><div class="h2">${_t("Règles de résolution")}</div><p class="plead t-3">${esc(m.rules)}</p>${m.parent?'':`<p class="plead t-3">${_t("Chaque part gagnante rapporte 1 $. Les parts perdantes ne valent plus rien.")}</p>`}</section></div></div>
 <div class="mbar"><button class="btn b-yes" data-a="bet" data-m="${id}" data-s="oui">${mxH(id,'oui',m.p)}<span class="mb-t">${buyLbl(id,'oui',m.p)}</span></button><button class="btn b-no" data-a="bet" data-m="${id}" data-s="non">${mxH(id,'non',m.p)}<span class="mb-t">${buyLbl(id,'non',100-m.p)}</span></button></div>`;}

