/* ===================== Chat ===================== */
function mostCited(){const c={};for(const x of room('general').msgs){const mm=(x.text||'').match(/#([a-z0-9-]+)/g);if(mm)mm.forEach(t=>{const id=t.slice(1);if(MK[id])c[id]=(c[id]||0)+1;});if(x.bet&&MK[x.bet.m])c[x.bet.m]=(c[x.bet.m]||0)+1;}let best='btc150k',bv=0;for(const k in c)if(c[k]>bv){bv=c[k];best=k;}return MK[best];}
function tribHead(rid){const r=room(rid);let title=esc(roomLabel(rid)),sub='';if(r.kind==='global'){title='# '+_t('Général');sub=`${_t("Salon ouvert à tous.")} <span data-online>${F.int(S.online)}</span> ${_t("connectés.")}`;}else if(r.kind==='market'){const m=MK[rid.slice(2)];title='# '+m.id;sub=`${_t("Chat du marché « {0} ».",[esc(m.short)])} <a class="link" href="#marche-${m.id}">${_t("Ouvrir le marché")}</a>`;}else if(r.kind==='dm'){sub=_t("Conversation privée.");}else if(r.kind==='clan'){sub=`${_t("Live chat du clan.")} <a class="link" href="#clan-${rid.slice(5)}">${_t("Voir le clan")}</a>`;}else if(r.kind==='vip'){title='# Salon VIP';sub=_t("Le salon des Ascendant, Immortel et Radiant.");}
 return `<div class="chat-h pb-4"><div class="tt"><div><h2>${title}</h2><div class="sub">${sub}</div></div>${r.kind==='market'?`<div class="seg"><button class="${S.ui.mtab==='live'?'on':''}" data-a="mtab" data-v="live">${_t("En direct")}</button><button class="${S.ui.mtab==='top'?'on':''}" data-a="mtab" data-v="top">${_t("Les plus utiles")}</button></div>`:''}</div></div>`;}
function vipH(){const L=conds(6),miss=L.filter(c=>!c.ok);const fake=vipFake();
 return `<section class="pn chat trib pos-rel"><div class="chat-h pb-4"><div class="tt"><div><h2>${_t("# Salon VIP")}</h2><div class="sub">${_t("Le salon des Ascendant, Immortel et Radiant. 38 joueurs y discutent en ce moment.")}</div></div></div></div><div class="vipprev"><div class="blur">${fake.map(([u,t])=>msgH(mkMsg({u,k:'msg',text:t,r:{'🔥':Math.round(5+R()*30)}}))).join('')}</div><div class="over"><div>${emb(6,0,'xl')}<b class="t-3">${_t("Réservé au rang Ascendant")}</b><p class="muted t-2">${_t("Il te manque : {0}.",[miss.map(c=>c.label.toLowerCase()).join(', ')])}</p><button class="btn b-ink full" data-a="lock" data-g="vip">${_t("Voir ce qu’il me manque")}</button><a class="btn b-ghost full" href="#rang">${_t("Mon rang")}</a></div></div></div></section>`;}
function vChat(){const rid=S.ui.room;room(rid).unread=0;const mc=typeof myClan==='function'?myClan():null;if(mc){const cr=room('clan:'+mc.id);cr.name=mc.name;cr.kind='clan';if(!cr.msgs.length&&typeof clanSeedRoom==='function')clanSeedRoom(mc);}const dms=Object.keys(S.rooms).filter(k=>k.startsWith('dm:'));const rb=(id,label,right)=>`<button class="room${rid===id?' on':''}" data-a="troom" data-room="${id}"><span class="nm">${label}</span>${right!==undefined?right:`<span data-unread="${id}">${unr(id)}</span>`}</button>`;
 const left=`<aside class="pn rooms t-rooms"><div class="rh"><span><i class="rdot" aria-hidden="true"></i>${_t("Live chat")}</span></div>${rb('general',`${_t("{0} Général",[ic('chat',15)])}`,`<span class="cnt"><span data-online>${F.int(S.online)}</span></span>`)}${rb('vip',`${_t("{0} Salon VIP",[ic(can('vip')?'crown':'lock',15)])}`,can('vip')?undefined:`<span class="lk">${_t("Ascendant")}</span>`)}${mc?rb('clan:'+mc.id,`${emblemH(mc,15)} ${esc(mc.name)}`):''}<a class="room" href="#clans"><span class="nm">${ic('shield',15)} ${mc?_t("Clans"):_t("Rejoindre un clan")}</span></a>
 <div class="rh"><span>${_t("Chats des marchés")}</span></div>${MARKETS.map(m=>rb('m:'+m.id,bidi('#'+m.id),`<span class="row-c"><span data-unread="m:${m.id}">${unr('m:'+m.id)}</span><span class="cnt" data-monline="${m.id}">${F.int(m.online)}</span></span>`)).join('')}
 <div class="rh"><span>${_t("Messages privés")}</span></div>${dms.length?dms.map(d=>rb(d,`${avH(d.slice(3),22,'span')} ${esc(userOf(d.slice(3)).n)}`)).join(''):`<p class="sub p-1-3-2">${_t("Ouvre le profil d’un joueur pour lui écrire.")}</p>`}</aside>`;
 const chips=['general',...(mc?['clan:'+mc.id]:[]),'vip',...MARKETS.slice(0,6).map(m=>'m:'+m.id),...dms].map(id=>`<button class="${rid===id?'on':''}${mc&&id==='clan:'+mc.id?' clanr':''}" data-a="troom" data-room="${id}">${id==='vip'&&!can('vip')?ic('lock',13):''}${mc&&id==='clan:'+mc.id?emblemH(mc,18):''}${esc(roomLabel(id))}${id==='general'||id==='vip'?'':`<span data-unread="${id}">${unr(id)}</span>`}</button>`).join('')+`<a class="chipl" href="#clans">${_t("{0} Clans",[ic('shield',13)])}</a>`;
 const center=rid==='vip'&&!can('vip')?vipH():chatH(rid,'trib',tribHead(rid));
 return `<div class="wrap tribw"><h1 class="vhid">${_t("Live chat")}</h1><div class="g-trib">${left}<div class="col gap-3"><div class="mobrooms">${chips}</div>${center}</div>${tribInfoH(rid)}</div></div>`;}
/* Colonne de droite du chat (1 280 px et plus) : ce qu'il faut savoir du salon ouvert. Un salon de marché montre son
   marché et la paire Oui / Non ; un salon de clan, le clan et ses membres ; une conversation privée, le joueur ; le salon
   Général et le salon VIP, le marché le plus cité dans le chat et les joueurs en ligne. Les règles du chat, partout. */
function tribMarcheH(m,k){return `<section class="pn pad tri-m"><div class="sub mb-2">${k}</div><a class="h2 d-block lh-snug" href="#marche-${m.id}">${esc(m.q)}</a><div class="d-flex ai-base gap-3 mt-3 mb-3"><b class="num t-5" data-mp="${m.id}">${F.pct(m.p)}</b><span class="delta ${m.p>=m.d0?'up':'dn'}" data-md="${m.id}">${F.pts(m.p-m.d0)}</span></div><div class="trail" data-trail="${m.id}"></div><div class="hbtns mt-4"><button class="btn b-yes grow" data-a="bet" data-m="${m.id}" data-s="oui">${_t("Oui")} <span data-mc="${m.id}">${F.c(m.p)}</span></button><button class="btn b-no grow" data-a="bet" data-m="${m.id}" data-s="non">${_t("Non")} <span data-mcn="${m.id}">${F.c(100-m.p)}</span></button></div></section>`;}
function tribGensH(titre,sub,L){return `<section class="pn pad"><div class="h2">${titre}</div><div class="sub mb-2">${sub}</div>${L.map(u=>`<a class="prow" href="${uHref(u)}"><span class="pl">${avH(u,32,'span')}<span class="nm">${esc(userOf(u).n)}</span></span>${rk(userOf(u).t,userOf(u).d)}</a>`).join('')}</section>`;}
function tribInfoH(rid){const r=room(rid);let haut;
 if(r.kind==='market'&&MK[rid.slice(2)]){const m=MK[rid.slice(2)];haut=tribMarcheH(m,_t(m.cat));}
 else if(r.kind==='clan'&&typeof CK!=='undefined'&&CK[rid.slice(5)]){const c=CK[rid.slice(5)],L=[...(myClan()===c?['me']:[]),...clanMates(c)];
  haut=`<section class="pn pad"><a class="tri-id" href="#clan-${c.id}">${emblemH(c,48)}<span class="hub-n2"><b><span class="hub-nm">${esc(c.name)}</span><span class="ctg${clanWorldRank(c)<=3?' gold':''}">${esc(c.tag)}</span></b><small>${clanPosTxt(c)}</small></span></a><div class="calc mt-3"><div class="line"><span>${_t("Score")}</span><b>${F.int(c.score)}</b></div><div class="line"><span>${_t("Membres")}</span><b>${F.int(clanMembersN(c))}</b></div></div><a class="btn b-white full mt-4" href="#clan-${c.id}">${_t("Voir le clan")}</a></section>${L.length?tribGensH(_t("Membres"),_t("{0} membres",[F.int(clanMembersN(c))]),L.slice(0,8)):''}`;}
 else if(r.kind==='dm'){const u=rid.slice(3),U=userOf(u);
  haut=`<section class="pn pad"><a class="tri-id" href="${uHref(u)}">${avH(u,48,'span')}<span class="hub-n2"><b><bdi dir="ltr" class="hub-nm">${esc(U.n)}</bdi>${typeof tagH==='function'?tagH(u,1):''}</b><small>${rankName(U.t,U.d)}</small></span></a>${USERS[u]?`<div class="calc mt-3"><div class="line"><span>${_t("Précision")}</span><b>${F.pct(U.acc)}</b></div><div class="line"><span>${_t("Profit de la saison")}</span><b class="${plc(U.profit)}">${bidi((U.profit>=0?'+':'−')+plain(F.usd0(Math.abs(U.profit))))}</b></div></div>`:''}<a class="btn b-white full mt-4" href="${uHref(u)}">${_t("Voir le profil")}</a></section>`;}
 else{const m=mostCited();haut=tribMarcheH(m,_t("Le marché le plus cité dans le chat"))+tribGensH(_t("En ligne"),`<span data-online>${F.int(S.online)}</span> ${_t("personnes")}`,['satoshi','lea','maxou','karim','ines','sofia']);}
 return `<aside class="col t-right">${haut}
 <section class="pn pad"><div class="h2 row-c">${_t("{0} Règles du chat",[ic('shield',18)])}</div><p class="sub t-2 mt-3 lh-p">${_t("Les mises partagées sont vérifiées : impossible d’annoncer une mise que tu n’as pas faite.")}</p><p class="sub t-2 mt-2 lh-p">${_t("Pas de liens d’affiliation ni de conseils payants.")}</p></section></aside>`;}

/* ===================== Classement ===================== */
const lbPos=P=>({Semaine:Math.max(1,Math.round(S.me.pos*.24)),Mois:Math.max(1,Math.round(S.me.pos*.63)),Saison:S.me.pos})[P];
function lbRows(P){const k={Semaine:.08,Mois:.3,Saison:1,'Mes amis':1,'Mon clan':1}[P]||1;let ids=USER_IDS.slice();if(P==='Mes amis')ids=ids.filter(u=>friendsOf().includes(u));if(P==='Mon clan')ids=[];return ids.map(u=>{const U=userOf(u),r=rng(hash(u+P));return {u,profit:U.profit*k*(P==='Saison'||P==='Mes amis'?1:(.6+r()*.8)),acc:U.acc,bets:Math.round(U.bets*(P==='Saison'||P==='Mes amis'?1:k*1.5+.04))};}).sort((a,b)=>b.profit-a.profit);}
const lbRank=u=>lbRows('Saison').findIndex(x=>x.u===u)+1;
function lrH(x,pos){const me=x.u==='me',U=userOf(x.u);return `<div class="lr${me?' me':''}${pos<=3?' podium':''}" data-href="${uHref(x.u)}"><span class="pos c-pos">${F.int(pos)}</span><span class="pl c-pl">${avH(x.u,32,'span')}<span class="nm"><a class="lbn" href="${uHref(x.u)}"><bdi dir="ltr">${esc(U.n)}</bdi></a>${me?`<span class="lbme">${_t(' (toi)')}</span>`:''}${tagH(x.u)}</span></span><span class="c-rk">${rk(U.t,U.d)}</span><span class="r c-pr"><b class="num ${plc(x.profit)} t-4">${bidi((x.profit>=0?'+':'−')+plain(F.usd0(Math.abs(x.profit))))}</b></span><span class="r c-acc">${F.pct(x.acc)}</span><span class="r c-bets">${F.int(x.bets)}</span><span class="r c-fol">${me?`<a class="btn b-ink sm" href="#rang">${_t("Mon rang")}</a>`:followBtn(x.u)}</span></div>`;}
function vBoard(){const P=S.ui.lbp,rows=lbRows(P),r=myRank(),pf=portfolio(),pg=progress(),st=stats();const myP={Semaine:S.me.played?62:0,Mois:S.me.played?184:0,Saison:pf.profit,'Mes amis':pf.profit,'Mon clan':pf.profit}[P];const meRow={u:'me',profit:myP,acc:st.acc,bets:S.me.played};
 let body;if(P==='Mon clan'){const c=typeof myClan==='function'?myClan():null;if(!c)body=`<div class="empty">${_t("Tu n’as pas encore de clan.")} <a class="link" href="#clans">${_t("Rejoins-en un")}</a> ${_t("pour te mesurer à ses membres chaque semaine.")}</div>`;else{const all=clanWeekRows(c);body=all.map((x,i)=>lrH(x,i+1)).join('')+`<div class="gap"><a class="link" href="#clan-${c.id}">${_t("Classement de la semaine de {0} · voir le clan",[esc(c.name)])}</a></div>`;}}else if(P==='Mes amis'){const all=(S.me.logged?[...rows,meRow]:rows.slice()).sort((a,b)=>b.profit-a.profit);body=all.map((x,i)=>lrH(x,i+1)).join('')+(rows.length?'':`<div class="empty">${_t("Suis des joueurs pour les retrouver ici.")} <a class="link" href="#amis">${_t("Trouver des amis")}</a></div>`);}else{const top=rows.slice(0,10);body=top.map((x,i)=>lrH(x,i+1)).join('')+(S.me.logged?(top.length?'<div class="gap">…</div>':'')+lrH(meRow,lbPos(P)):'');}   /* les points de suspension seulement s'il y a des lignes au-dessus */
 const SC=P==='Mes amis'?1:P==='Mon clan'?2:0,PER=S.ui.lbper||'Saison';
 return `<div class="wrap lbw">${typeof hubSwH==='function'?hubSwH('joueurs'):''}<div class="pagehead"><div><h1 class="ptitle">${_t("Classement")}</h1><p class="plead">${_t("Saison 3. Fin dans 12 jours. 23 000 $ répartis entre les 100 premiers, et le rang Radiant pour le top 100.")}</p></div><div class="lbh"><div class="chips lbsc" role="group" aria-label="${_t('Joueurs affichés')}">${[[PER,_t('Tous les joueurs'),0],['Mes amis',_t('Mes amis'),1],['Mon clan',_t('Mon clan'),2]].map(([v,l,k])=>`<button class="chip${SC===k?' on':''}" data-a="lbp" data-v="${v}">${l}</button>`).join('')}</div>${SC===0?`<div class="seg lbper">${['Semaine','Mois','Saison'].map(p=>`<button class="${P===p?'on':''}" data-a="lbp" data-v="${p}">${_t(p)}</button>`).join('')}</div>`:`<span class="lbper cap">${SC===1?_t('Profit de la saison'):_t('Profit de la semaine')}</span>`}</div></div>
 <div class="g-side"><section class="pn lb clip"><div class="lh"><span>#</span><span>${_t("Joueur")}</span><span>${_t("Rang")}</span><span class="r">${_t("Profit")}</span><span class="r">${_t("Précision")}</span><span class="r">${_t("Paris")}</span><span></span></div>${body}</section>
 <aside class="col rail-fixe">${S.me.logged?'':guestRankH()}<a class="pn pad${S.me.logged?'':' hide'} d-block" href="#rang"><div class="h2">${_t("Ta saison")}</div><div class="row-c gap-4 mt-4">${emb(r.t,r.d,'lg')}<div><div class="num t-5 fw-6">${F.ord(S.me.pos)}</div><div class="sub">${_t("sur {0} joueurs, {1}",[F.int(Math.max(38900,S.me.pos)),rankName(r.t,r.d)])}</div></div></div><div class="xpbar sm mt-4"><i style="width:${pg.pct}%"></i></div><div class="xprow"><span>${pg.nx?`${_t("Plus que <b>{0}</b> pour {1}",[F.xp(pg.left),rankName(pg.nx.t,pg.nx.d)])}`:_t("Rang maximal")}</span><span class="link">${_t("Voir ce qu’il me faut")}</span></div></a>
 <section class="pn pad"><div class="h2">${_t("Les rangs")}</div><div class="sub">${_t("Clique sur un rang pour voir ses conditions.")}</div><div class="ladder l3">${TIERS.map((T,i)=>tierTile(i)).join('')}</div></section>
 <section class="pn pad"><div class="h2 mb-2">${_t("Récompenses de la saison")}</div><div class="line"><span>${_t("1re place")}</span><b>${F.usd0(5000)}</b></div><div class="line"><span>${_t("De la 2e à la 10e place")}</span><b>${_t('{0} chacun',[F.usd0(1000)])}</b></div><div class="line"><span>${_t("De la 11e à la 100e place")}</span><b>${_t('{0} chacun',[F.usd0(100)])}</b></div><p class="sub mt-2">${_t("Les gains sont versés en USDC sur ton solde à la fin de la saison.")}</p></section></aside></div></div>`;}

/* ===================== Écrans « argent » sur ordinateur (troisième passe) =====================
   À partir de 880 px, le portefeuille, le dépôt, le retrait, le profil et le rang ont leur propre gabarit, composé sur la
   grille de 12 colonnes (docs/DESIGN-SYSTEM.md, § 3) ; en dessous, leur gabarit de téléphone ne change pas. Passer le
   palier redessine l'écran (js/refonte.js). */
function argentOrdi(){return typeof matchMedia==='function'&&matchMedia('(min-width:880px)').matches;}

/* ===================== Rang ===================== */
const EARN=[{l:_t("Placer un pari"),s:_t("Sur n’importe quel marché, dès 1 $"),xp:'+10',href:'#accueil',b:_t("Parier")},{l:_t("Gagner un pari éclair"),s:_t("Un pari toutes les 45 secondes : +10 XP la mise, +40 XP si tu gagnes"),xp:'+50',href:'#eclair',b:_t("Jouer")},{l:_t("Écrire dans le live chat"),s:_t("Live chat global ou d’un marché, jusqu’à 20 XP par jour"),xp:'+2',href:'#chat',b:_t("Discuter")},{l:_t("Partager une mise"),s:_t("Puis +20 XP chaque fois que quelqu’un la suit"),xp:'+5',href:'#chat',b:_t("Partager")},{l:_t("Suivre la mise d’un joueur"),s:_t("Depuis une carte de mise dans un chat"),xp:'+5',href:'#chat',b:_t("Voir les mises")},{l:_t("Créer un pari validé"),s:_t("Quand la communauté valide ta proposition"),xp:'+50',href:'#creer',b:_t("Créer")},{l:_t("Déposer des fonds"),s:_t("Une fois par jour, en crypto"),xp:'+100',href:'#depot',b:_t("Déposer")}];
function tierTile(i){const r=myRank();const cls=i===r.t?'cur':i<r.t?'past':'lockd';return `<button class="tier ${cls}" data-a="tier" data-t="${i}"${cls==='cur'&&S.me.logged?` data-you="${_t('Toi')}"`:''}>${emb(i,i===r.t?r.d:(i<r.t?2:0))}<b>${TIERS[i].name}</b><small>${i===8?_t("Top 100"):F.xp(DIV_XP[i][0])}</small></button>`;}
function missionsH(){return S.me.missions.map(m=>`<div class="mis"><div class="ml"><b>${m.label}</b><small>${_t("{0} sur {1}, +{2} XP",[m.have,m.goal,m.xp])}</small></div>${m.claimed?`<span class="xpc">${_t("Récupéré")}</span>`:m.have>=m.goal?`<button class="btn b-ink sm" data-a="claim" data-id="${m.id}">${_t("Récupérer {0} XP",[m.xp])}</button>`:`<a class="btn b-ghost sm" href="${m.go}">${_t("Y aller")}</a>`}<div class="xpbar sm"><i style="width:${Math.min(100,m.have/m.goal*100)}%"></i></div></div>`).join('');}
function vRank(){const r=myRank(),pg=progress(),nt=r.t<8?r.t+1:null;const cur=TIERS[r.t];
 const blockedTxt=pg.blocked&&pg.nx?`${_t("Ton XP suffit pour {0}. Remplis les conditions ci-dessous pour monter.",[rankName(pg.nx.t,0)])}`:'';
 /* les blocs de l'écran ; c : classes ajoutées sur ordinateur (place sur la grille) */
 const heros=(c,bas)=>`<section class="pn pad rk-hero${c}">${emb(r.t,r.d,'xxl')}<div><div class="kick">${_t("Ton rang, saison 3")}</div><h1>${rankName(r.t,r.d)}</h1>${pg.blocked&&pg.nx?lastStepH(pg):`<div class="mt-5"><div class="xpbar"><i style="width:${pg.pct}%"></i></div><div class="xprow"><span><bdi dir="ltr"><b>${F.int(S.me.xp)}</b> / ${F.xp(pg.next)}</bdi></span><span>${pg.nx?`${_t("Plus que <b>{0}</b> pour {1}",[F.xp(pg.left),rankName(pg.nx.t,pg.nx.d)])}`:_t("Rang maximal")}</span></div></div><div class="hbtns mt-5"><a class="btn b-pri" href="#eclair">${ic('bolt',16,'#fff')} <span>${_t("Gagner de l’XP")}</span></a><a class="btn b-white" href="#classement">${_t("Voir le classement")}</a></div>`}</div>${bas||''}</section>`;
 const palier=c=>nt!==null?`<section class="pn pad${c}"><div class="ph"><div><div class="h2">${_t("Prochain palier : {0} I",[TIERS[nt].name])}</div><div class="sub">${_t("Il faut remplir toutes les conditions pour changer de palier.")}</div></div>${emb(nt,0,'e44')}</div>${conds(nt).map(c=>condH(c,c.k==='xp')).join('')}</section>`:'';
 const missions=c=>`<section class="pn pad${c}"><div class="ph mb-1"><div><div class="h2">${_t("Missions du jour")}</div><div class="sub">${_t("Renouvelées chaque jour à minuit.")}</div></div><span class="xpc">${_t("Jusqu’à +130 XP")}</span></div><div data-missions>${missionsH()}</div></section>`;
 const gagner=c=>`<section class="pn pad${c}"><div class="h2">${_t("Comment gagner de l’XP")}</div>${EARN.map(e=>`<div class="earn"><div class="el"><b>${e.l}</b><small>${e.s}</small></div><span class="xv">${bidi(e.xp+' XP')}</span><a class="btn b-ghost sm" href="${e.href}">${e.b}</a></div>`).join('')}</section>`;
 const fonctions=c=>`<section class="pn pad${c}"><div class="h2">${_t("Ce que ton rang débloque")}</div><div class="sub mb-2">${_t("Chaque fonction de Wimoro s’ouvre à un rang précis.")}</div><div class="perks">${FEATURES.map(f=>f.t<=r.t?`<${f.href?`a href="${f.href}"`:`button data-a="${f.action||'noop'}"`} class="perk w-full"><span class="pi">${ic(f.ic,16)}</span>${f.label}<span class="xpc ms-auto">${_t("Débloqué")}</span></${f.href?'a':'button'}>`:`<button class="perk off w-full" data-a="lock" data-g="${f.g}"><span class="pi">${ic('lock',15,'#A3A8B2')}</span>${f.label}${rk(f.t,0)}</button>`).join('')}</div></section>`;
 const plafond=c=>`<section class="pn pad${c}"><div class="h2 mb-2">${_t("Des mises sans plafond")}</div><p class="sub lh-p">${_t("Ton rang ne limite jamais le montant d’un pari : seuls ton solde et la liquidité du marché comptent.")}</p></section>`;
 const echelle=`<div class="ladder">${TIERS.map((T,i)=>tierTile(i)).join('')}</div>`;
 const tous=_t("Du Fer au Radiant, trois divisions par rang.");
 if(!argentOrdi())return `<div class="wrap"><div class="g-side"><div class="col">${heros('')}${palier('')}${missions('')}${gagner('')}</div><div class="col">${fonctions('')}${plafond('')}</div></div>
 <section class="pn pad mt-6"><div class="ph"><div><div class="h2">${_t("Tous les rangs")}</div><div class="sub">${tous}</div></div></div>${echelle}</section>${typeof demoRankH==='function'?`<div class="mt-6">${demoRankH()}</div>`:''}</div>`;
 /* ordinateur : le rang et l'échelle des neuf rangs d'un coup d'œil, le palier suivant à côté ; dessous, comment progresser */
 const demo=typeof demoRankH==='function'?demoRankH():'';
 return `<div class="wrap rang-o"><div class="grille12">${heros(nt!==null?' s8':'',`<div class="rk-lad"><div class="rk-lad-h"><h2 class="h2">${_t("Tous les rangs")}</h2><span class="sub m-0">${tous}</span></div>${echelle}</div>`)}${palier(' s4')}
 <div class="col s8">${gagner('')}${fonctions('')}</div><div class="col s4">${missions('')}${plafond('')}</div>${demo?`<div class="rang-demo">${demo}</div>`:''}</div></div>`;}
function refreshRankBits(){if((S.ui.route||'').startsWith('rang'))render(false);else{const m=$('[data-missions]');if(m)m.innerHTML=missionsH();}}

/* ===================== Profil ===================== */
function posTable(){const L=S.me.positions;if(!L.length)return `<div class="empty">${_t("Aucune position ouverte.")} <a class="link" href="#accueil">${_t("Parier sur un marché")}</a></div>`;const pf=portfolio();
 return `<div class="pos-t"><div class="ph2"><span>${_t("Marché")}</span><span>${_t("Côté")}</span><span class="r">${_t("Parts")}</span><span class="r">${_t("Prix moyen")}</span><span class="r">${_t("Prix actuel")}</span><span class="r">${_t("Valeur")}</span><span class="r">${_t("Résultat")}</span></div>${L.map(p=>{const m=MK[p.m],k=p.m+'-'+p.s,pr=p.s==='oui'?m.p:100-m.p,v=posPnl(p);return `<div class="pr2" data-href="#marche-${m.id}"><span class="q2">${esc(m.q)}${copyTagH(p)}${guardTagH(p)} ${shareBtnH('bet',{m:m.id,s:p.s})}</span><span class="c-x"><span class="sidechip ${p.s}">${p.s==='oui'?_t("Oui"):_t("Non")}</span></span><span class="r c-x">${F.d1(p.sh)}</span><span class="r c-x">${F.c(p.avg)}</span><span class="r c-x" data-ppr="${k}">${F.c(pr)}</span><span class="r c-x" data-pv="${k}">${F.usd(posValue(p))}</span><span class="r"><b class="num ${plc(v)} t-4" data-ppnl="${k}">${F.signed(v)}</b></span></div>`;}).join('')}<div class="pr2 cur-def">${_t("<b>Total</b>")}<span class="c-x"></span><span class="c-x"></span><span class="c-x"></span><span class="c-x"></span><b class="r c-x num t-4" data-live="pvalue">${F.usd(pf.value)}</b><span class="r"><b class="num ${plc(pf.unreal)} t-4" data-live="punreal">${F.signed(pf.unreal)}</b></span></div></div>`;}
/* lim (facultatif) : nombre de lignes d'historique affichées, la suite à la demande (colonne Historique du portefeuille sur ordinateur) */
function ptabH(t,lim){if(t==='positions')return posTable()+ordersTableH();if(t==='mine')return myBetsH();
 if(t==='history'){const H=S.me.history,L=lim&&H.length>lim&&!S.ui.histAll?H.slice(0,lim):H;return `<div class="p-1-5-3">${H.length?L.map(h=>`<div class="act"><span><span class="sidechip ${h.s}" style="margin-inline-end:8px">${h.k==='flash'?(h.eq?_t("Égalité"):h.s==='oui'?_t("Haut"):_t("Bas")):(h.s==='oui'?_t("Oui"):_t("Non"))}</span>${esc(h.m&&MK[h.m]?MK[h.m].q:h.q)}<small class="d-block mt-1">${histKind(h)}, ${ago(h.at)}</small></span><span class="hpnl"><b class="num ${plc(h.pnl)} t-4 nowrap">${F.signed(h.pnl)}</b>${h.pnl>0.004?shareBtnH('win',{q:h.m&&MK[h.m]?MK[h.m].q:h.q,s:h.s,pnl:h.pnl}):''}</span></div>`).join('')+(lim&&H.length>lim?`<button class="link t-2 hist-plus" data-a="hist-all" aria-expanded="${!!S.ui.histAll}">${S.ui.histAll?_t("Afficher moins"):_t("Tout l’historique ({0})",[F.int(H.length)])}</button>`:''):`<div class="empty">${_t("Pas encore d’historique.")} <a class="link" href="#accueil">${_t("Parier sur un marché")}</a></div>`}</div>`;}
 if(t==='badges')return `<div class="p-2-5-4">${BADGES.map(b=>{const on=S.me.badges.includes(b.id);return `<div class="act bdg"><span class="bdg-i${on?' on':''}">${ic(on?b.ic:'lock',18)}</span><span class="bdg-t"><b class="c-1">${b.n}</b><small>${b.how}</small></span>${on?`<span class="bdg-ok">${_t('Obtenu')}</span>`:''}</div>`;}).join('')}</div>`;
 return `<form class="col p-5 gap-4 maxw-card" data-form="settings"><div class="field"><label for="pseudo">${_t("Pseudo")}</label><input id="pseudo" name="pseudo" value="${esc(S.me.n)}" maxlength="20" pattern="[A-Za-z0-9._]{3,20}" required><span class="sub">${_t("3 à 20 caractères : lettres, chiffres, point ou tiret bas.")}</span></div><button class="btn b-ink self-start" type="submit">${_t("Enregistrer")}</button><hr><div><div class="h2 t-3">${_t("Compte")}</div><p class="sub mt-1">${S.auth.demo?_t("Compte démo"):esc((accountOfMe()||{}).email||_t("Compte lié à un portefeuille"))}</p><div class="kycrow">${S.me.kyc?`<span class="kyc-badge ok">${_t("{0} KYC vérifié",[ic('check',13,'#2448FF',2.6)])}</span>`:`<span class="kyc-badge">${_t("{0} KYC non fait : crypto uniquement",[ic('lock',13)])}</span><button class="btn b-ink sm" type="button" data-a="kyc">${_t("Faire le KYC")}</button>`}</div></div><hr><div class="swrow"><div><div class="h2 t-3">${_t("Mode sombre")}</div></div><button type="button" class="sw${isDark()?' on':''}" role="switch" aria-checked="${isDark()}" aria-label="${_t("Mode sombre")}" data-a="theme"><i></i></button></div>${settingsExtraH()}<hr><div><div class="h2 t-3">${_t("Démo")}</div><p class="sub mt-1">${_t("Tes progrès sont gardés dans ce navigateur.")}</p><div class="hbtns mt-3"><button class="btn b-ghost" type="button" data-a="reset">${_t("{0} Réinitialiser la démo",[ic('refresh',16)])}</button><button class="btn b-ink" type="button" data-a="logout">${_t("{0} Se déconnecter",[ic('logout',16)])}</button></div></div></form>`;}
function vProfile(){const r=myRank(),st=stats(),pf=portfolio(),pg=progress(),t=['badges','settings','mine'].includes(S.ui.ptab)?S.ui.ptab:'badges';
 if(argentOrdi())return profOrdiH(r,st,pf,pg,t);
 return `<div class="wrap prof"><section class="pn clip"><div class="pf-top"><div class="pf-id"><span class="av t-me${avClass('me')}" style="background:${S.me.color}">${avInner('me',88)}</span><div><h1>${esc(S.me.n)} ${tagH('me')}</h1>${S.me.bio?`<p class="pf-bio">${esc(S.me.bio)}</p>`:''}<div class="pf-meta"><a href="#rang">${rk(r.t,r.d)}</a><span>${_t("Membre depuis {0}",[esc(S.me.since||_t("aujourd’hui"))])}</span><span>${_t("{0} abonné{1}",[F.int(S.me.followers||0),(S.me.followers||0)>1?'s':''])}</span><span>${_t("{0} abonnements",[S.me.following.length])}</span>${visMetaH()}</div></div></div>
  <div class="hbtns own"><a class="btn b-pri" href="#modifier">${_t("Modifier le profil")}</a><button class="btn b-ink" data-a="copylink" data-v="#profil">${ic('share',16)} <span>${_t("Partager")}</span></button></div></div>
  <div class="pf-stats"><div><small>${_t("Profit total")}</small><b class="num ${plc(pf.profit)}" data-live="profit">${F.signed(pf.profit)}</b></div><div><small>${_t("Précision")}</small><b class="num">${F.pct(st.acc)}</b></div><div><small>${_t("Paris joués")}</small><b class="num">${F.int(S.me.played)}</b></div><div><small>${_t("Série en cours")}</small><b class="num">${_t("{0} jours",[S.me.streak])}</b></div></div></section>
 ${profRankH(pg)}${acctH()}
 <section class="pn clip"><div class="wal-tabs"><div class="tabs ptabs">${[['badges',_t("Badges")],['settings',_t("Paramètres")],['mine',`${_t("Mes paris créés")}${(S.me.props||[]).length?' ('+S.me.props.length+')':''}`]].map(([k,l])=>`<button class="${t===k?'on':''}" data-a="ptab" data-v="${k}">${l}</button>`).join('')}</div></div><div data-ptab-body>${ptabH(t)}</div></section></div>`;}

/* Profil sur ordinateur : l'identité et le rang dans une colonne, les chiffres en bande, puis les badges et les réglages
   côte à côte (les onglets ne gardent que Paramètres et Mes paris créés : les badges sont toujours visibles). */
function profOrdiH(r,st,pf,pg,t){const t2=t==='mine'?'mine':'settings',nb=BADGES.filter(b=>S.me.badges.includes(b.id)).length,np=(S.me.props||[]).length;
 return `<div class="wrap prof prof-o"><div class="grille12"><div class="col prof-g">
 <section class="pn pad pf-carte"><span class="av t-me${avClass('me')}" style="background:${S.me.color}">${avInner('me',88)}</span><div class="pf-nom"><h1>${esc(S.me.n)} ${tagH('me')}</h1>${S.me.bio?`<p class="pf-bio">${esc(S.me.bio)}</p>`:''}</div><div class="pf-meta"><a href="#rang">${rk(r.t,r.d)}</a><span>${_t("Membre depuis {0}",[esc(S.me.since||_t("aujourd’hui"))])}</span><span>${_t("{0} abonné{1}",[F.int(S.me.followers||0),(S.me.followers||0)>1?'s':''])}</span><span>${_t("{0} abonnements",[S.me.following.length])}</span>${visMetaH()}</div>
  <div class="hbtns own"><a class="btn b-pri" href="#modifier">${_t("Modifier le profil")}</a><button class="btn b-ink" data-a="copylink" data-v="#profil">${ic('share',16)} <span>${_t("Partager")}</span></button></div></section>
 ${profRankH(pg)}</div>
 <div class="col prof-d"><section class="pn pf-stats"><div><small>${_t("Profit total")}</small><b class="num ${plc(pf.profit)}" data-live="profit">${F.signed(pf.profit)}</b></div><div><small>${_t("Précision")}</small><b class="num">${F.pct(st.acc)}</b></div><div><small>${_t("Paris joués")}</small><b class="num">${F.int(S.me.played)}</b></div><div><small>${_t("Série en cours")}</small><b class="num">${_t("{0} jours",[S.me.streak])}</b></div></section>
 <div class="prof-cols"><section class="pn clip"><div class="pn-tete"><h2 class="h2">${_t("Badges")}</h2><span class="sub m-0">${_t("{0} sur {1}",[nb,BADGES.length])}</span></div>${ptabH('badges')}</section>
 <section class="pn clip"><div class="wal-tabs"><div class="tabs ptabs">${[['settings',_t("Paramètres")],['mine',`${_t("Mes paris créés")}${np?' ('+np+')':''}`]].map(([k,l])=>`<button class="${t2===k?'on':''}" data-a="ptab" data-v="${k}">${l}</button>`).join('')}</div></div><div data-ptab-body>${ptabH(t2)}</div></section></div></div></div></div>`;}

/* ===================== Joueur ===================== */
function playerBets(u){return MARKETS.slice().sort((a,b)=>hash(u+a.id)-hash(u+b.id)).slice(0,3).map(m=>{const r=rng(hash(u+m.id));const s=r()<m.p/100?'oui':'non';return {m,s,amt:Math.round(80+r()*1600),price:Math.max(3,Math.round((s==='oui'?m.p:100-m.p)-2-r()*6))};});}
function vPlayer(u){const U=USERS[u];if(!U)return vBoard();if(!canSeeProfile(u))return vPlayerLocked(u);const bets=playerBets(u);
 const msgs=[];for(const id in S.rooms)S.rooms[id].msgs.forEach(x=>{if(x.u===u&&x.k!=='evt')msgs.push({x,id});});msgs.sort((a,b)=>b.x.at-a.x.at);
 /* Ordinateur : la carte « Copier » rejoint la colonne de droite, au-dessus de ses derniers messages ; ses mises en cours
    occupent la colonne principale (grille .jg, css/screens.css). Téléphone : le même ordre qu'avant, carte « Copier » d'abord. */
 return `<div class="wrap jw"><nav class="crumbs mb-3"><a href="#classement">${_t("Classement")}</a><span>/</span><span>${esc(U.n)}</span></nav><section class="pn clip"><div class="pf-top"><div class="pf-id">${avH(u,88,'span')}<div><h1>${esc(U.n)} ${tagH(u)}</h1>${U.bio?`<p class="pf-bio">${esc(U.bio)}</p>`:''}<div class="pf-meta">${rk(U.t,U.d)}<span>${_t("{0} abonnés",[F.int(U.fol)])}</span></div></div></div><div class="hbtns pl3">${friendBtnH(u)}${followBtn(u).replace(' sm','')}${gateBtn('dm',ic('send',15)+_t(" Message privé"),'b-white',`data-u="${u}"`)}</div></div>
 <div class="pf-stats"><div><small>${_t("Profit de la saison")}</small><b class="num pl-up">+${F.usd0(U.profit)}</b></div><div><small>${_t("Précision")}</small><b class="num">${F.pct(U.acc)}</b></div><div><small>${_t("Paris joués")}</small><b class="num">${F.int(U.bets)}</b></div><div><small>${_t("Rang")}</small><b class="num">${rankName(U.t,U.d)}</b></div><div><small>${_t("Classement")}</small><b class="num">${F.ord(lbRank(u))}</b></div></div></section>
 <div class="g-side jg">${copyCardH(u)}<section class="pn pad jbets"><div class="h2">${_t("Ses mises en cours")}</div><div class="sub mb-2">${_t("Suis une mise pour parier comme {0}, au prix actuel.",[esc(U.n)])}</div>${bets.map(b=>`<div class="prow jbet"><div class="jbet-t"><a class="nm link c-1" href="#marche-${b.m.id}">${esc(b.m.q)}</a><div class="sub mt-1"><span class="sidechip ${b.s}">${b.s==='oui'?_t("Oui"):_t("Non")}</span> ${_t("{0} à {1}, prix actuel",[F.usd0(b.amt),F.c(b.price)])} <span data-${b.s==='oui'?'mc':'mcn'}="${b.m.id}">${F.c(b.s==='oui'?b.m.p:100-b.m.p)}</span></div></div>${can('follow')?`<button class="btn ${b.s==='oui'?'b-yes-soft':'b-no-soft'} sm" data-a="follow-pbet" data-m="${b.m.id}" data-s="${b.s}" data-u="${u}">${_t("Suivre")}</button>`:`<button class="btn b-ghost sm" data-a="lock" data-g="follow">${_t("{0} Suivre",[ic('lock',12)])}</button>`}</div>`).join('')}</section>
 <aside class="col jmsg"><section class="pn pad"><div class="h2 mb-1">${_t("Derniers messages")}</div>${msgs.slice(0,5).map(({x,id})=>`<div class="act"><span>${x.text?richText(x.text):x.bet?`${_t("A misé {0} sur {1}",[F.usd0(x.bet.amt),x.bet.s==='oui'?_t("Oui"):_t("Non")])}`:''}<small class="d-block mt-1">${esc(roomLabel(id))}, ${hhmm(x.at)}</small></span></div>`).join('')||`<p class="sub">${_t("Pas encore de message aujourd’hui.")}</p>`}</section></aside></div></div>`;}

/* ===================== Dépôt et retrait ===================== */
const fmtCoin=(v,c)=>NB(new Intl.NumberFormat(LOC,{maximumFractionDigits:COINS[c].dec}).format(v))+' '+c;
/* libellé d'un dépôt enregistré dans une autre langue : réaffiché dans la langue courante */
const depLabel=l=>l==='parrainage'?_t('Bonus de parrainage'):(l==='Crédit démo'||l===I18N.en['Crédit démo']||l===I18N.he['Crédit démo'])?_t('Crédit démo'):l;
function depsH(){const L=S.me.deps.slice(0,6);return L.map(d=>{const ok=d.conf>=d.need;if(d.method)return fiatDepRow(d,ok);return `<div class="dep"><span class="tk">${d.coin}</span><span class="dd"><b>${d.label?F.kv(esc(depLabel(d.label)),fmtCoin(d.amt,d.coin)):`${_tc("{0} sur {1}","réseau",[fmtCoin(d.amt,d.coin),d.net])}`}</b><small>${d.coin==='USDC'?'':`${_t("Converti en {0},",[F.usd(d.usd)])} `}${ago(d.at)}</small></span>${ok?`<span class="st-ok">${_t("{0} Crédité",[ic('check',13,'currentColor',2.6)])}</span>`:`<span class="st-wait">${_t("{0} / {1} confirmations",[d.conf,d.need])}<span class="bar"><i style="width:${d.conf/d.need*100}%"></i></span></span>`}</div>`;}).join('');}
function vDeposit(){const st=S.ui.dep,C=COINS[st.coin];if(!C.nets.includes(st.net))st.net=REC_NET[st.coin];const N=NETS[st.net],addr=addrFor(st.coin,st.net),pf=portfolio();const pend=S.me.deps.filter(d=>d.conf<d.need).reduce((a,d)=>a+d.usd,0);
 const tete=`<div class="pagehead"><div><h1 class="ptitle">${_t("Déposer des fonds")}</h1><p class="plead">${_t("Ton dépôt est crédité en dollars sur ton solde.")}</p></div><div class="seg"><button class="on">${_t("Déposer")}</button><a href="#retrait" class="p-2-3 r-sm t-2 fw-5 c-3">${_t("Retirer")}</a></div></div>`;
 const crypto=dMethod()==='crypto';
 /* crypto : 1. la crypto, 2. le réseau, 3. l'adresse d'envoi */
 const c1=`<section class="pn pad step"><div class="step-h"><i>1</i><h3>${_t("Choisis la crypto à envoyer")}</h3></div><div class="coins">${Object.entries(COINS).map(([k,c])=>`<button class="coin${st.coin===k?' on':''}" data-a="coin" data-v="${k}"><span class="ct"><b class="num">${k}</b>${st.coin===k?ic('check',18,'#2448FF',2.6):''}</span><b>${c.n}</b><small>${c.note}</small></button>`).join('')}</div></section>`;
 const c2=`<section class="pn pad step"><div class="step-h"><i>2</i><h3>${_t("Choisis le réseau")}</h3></div><div class="nets">${C.nets.map(n=>{const X=NETS[n];return `<button class="net${st.net===n?' on':''}" data-a="net" data-v="${n}"><span class="rad"></span><span class="nn"><b>${n}${REC_NET[st.coin]===n?`<span class="tag">${_t("Recommandé")}</span>`:''}</b><small>${X.d}</small></span><span class="nf">${_t("Frais : {0}",[X.fee])}<small>${X.time}</small></span></button>`;}).join('')}</div></section>`;
 const c3=`<section class="pn pad step"><div class="step-h"><i>3</i><h3>${_t("Envoie tes {0} à cette adresse",[st.coin])}</h3></div><div class="addr-w"><div class="qr">${qrSVG(addr)}</div><div class="col gap-4"><div class="sub m-0">${_t("Ton adresse de dépôt {0} sur {1}",[st.coin,st.net])}</div><div class="addr">${grp(addr)}</div><div class="warn">${ic('info',18,'#9A5B00')}<span>${_t("Envoie uniquement des {0} via le réseau {1}. Un autre jeton ou un autre réseau entraînera la perte des fonds.",[st.coin,st.net])}</span></div><div class="hbtns"><button class="btn b-pri" data-a="copy" data-v="${addr}">${_t("{0} Copier l’adresse",[ic('copy',16,'#fff')])}</button><button class="btn b-white" data-a="sim-dep">${_t("{0} J’ai envoyé les fonds",[ic('check',16)])}</button></div></div></div><hr class="mt-1 mb-1"><div class="conds4"><div><small>${_t("Dépôt minimum")}</small><b class="num">${fmtCoin(C.min,st.coin)}</b></div><div><small>${_t("Confirmations")}</small><b class="num">${N.conf}</b></div><div><small>${_t("Délai habituel")}</small><b class="num">${N.time.replace(_t("Environ "),'')}</b></div><div><small>${_t("Frais Wimoro")}</small><b class="num">${_t("Aucun")}</b></div></div></section>`;
 const solde=`<section class="pn pad"><div class="sub m-0">${_t("Ton solde disponible")}</div><div class="num balbig" data-bal>${F.bal(S.me.balance,true)}</div><hr><div class="line"><span>${_t("Dépôts en cours")}</span><b data-pend>${F.usd(pend)}</b></div><div class="line"><span>${_t("Valeur des positions")}</span><b data-live="pvalue">${F.usd(pf.value)}</b></div>${rgDepNoteH()}${S.me.depDay!==today()?`<div class="limit mt-3"><span>${_t("Ton premier dépôt du jour rapporte <b>+100 XP</b>")}</span>${ic('gift',16)}</div>`:''}</section>`;
 const recents=`<section class="pn pad"><div class="h2 mb-1">${_t("Dépôts récents")}</div><div data-deps>${depsH()}</div></section>`;
 if(!argentOrdi())return `<div class="wrap">${tete}
 <div class="g-dep"><div class="col">${methodsH('dep')}${crypto?c1+c2+c3:fiatDepH()}</div>
 <aside class="col">${solde}
 ${recents}
 ${refTeaserH()}${whyH()}</aside></div></div>`;
 /* ordinateur : le moyen, le formulaire, puis l'envoi (ou le paiement) avec son bouton, sur trois colonnes ; le solde sous le
    moyen, les dépôts récents sous la colonne la plus courte. « Pourquoi le KYC ? » n'y est pas : la barre du KYC et les
    moyens le disent déjà. */
 const fi=crypto?null:fiatDepParts();
 return `<div class="wrap argx">${tete}<div class="grille12 argx-g"><div class="col argx-m">${methodsH('dep')}${solde}</div><div class="col argx-f">${crypto?c1+c2:fi[0]+recents}</div><div class="col argx-s">${crypto?c3+recents:fi[1]}${refTeaserH()}</div></div></div>`;}
function simDepModal(){const st=S.ui.dep,C=COINS[st.coin];const def={USDC:50,USDT:50,ETH:.02,BTC:.001,SOL:.5}[st.coin];openModal(`<div class="md"><div class="md-h"><div><h3>${_t("Envoi de {0}",[st.coin])}</h3><p>${_t("Le dépôt passe par les confirmations du réseau {0}, puis il est crédité sur ton solde.",[st.net])}</p>${demoHint(_t('Indique le montant : aucun vrai transfert n’a lieu.'))}</div><button class="x" data-a="close" aria-label="${_t("Fermer")}">${ic('x')}</button></div><form class="col gap-4" data-form="simdep"><label class="amt"><input name="amt" data-simamt inputmode="decimal" value="${F.inp(def)}" autofocus aria-label="${_t("Montant")}"><span>${st.coin}</span></label><div class="line"><span>${_t("Crédité sur ton solde")}</span><b data-simusd>${F.usd(def*coinUSD(st.coin))}</b></div><div class="line"><span>${_t("Minimum")}</span><b>${fmtCoin(C.min,st.coin)}</b></div><p class="sub c-no" data-simerr></p><button class="btn b-pri lg full" type="submit">${_t('Envoyer les {0}',[st.coin])}</button></form></div>`);}
/* Déposer se fait en trois temps : 1. validation (limites de jeu responsable) ; 2. écriture — locale ici (les confirmations
   défilent puis le dépôt est crédité), par le serveur en mode serveur (srvDepot) ; 3. effets d'interface, les mêmes dans les
   deux modes : depDetecte, depCredite, depRendu. */
function startDeposit(amt){const st=S.ui.dep,N=NETS[st.net],usd=amt*coinUSD(st.coin);if(typeof rgDepOk==='function'&&!rgDepOk(usd))return;
 if(SRV()){srvDepot({method:'crypto',coin:st.coin,net:st.net,amt,usd:Math.round(usd*100)/100});return;}
 const d={coin:st.coin,net:st.net,amt,usd,at:now(),conf:0,need:Math.min(N.conf,12)};S.me.deps.unshift(d);depDetecte(d);depLocal(d,650);save();}
function depDetecte(d){if(d.method)toast({icon:'wallet',title:d.method==='bank'?_t("Virement en attente"):_t("Paiement en cours"),text:`${_t("{0} par {1}.",[F.usd(d.amt),d.net])}`});
 else{closeModal();toast({icon:'wallet',title:_t("Dépôt détecté"),text:`${_t("{0} sur {1}, en attente de confirmations.",[fmtCoin(d.amt,d.coin),d.net])}`});}
 refreshDeps();}
function depCredite(d){updateHeader();toast({tone:'blue',icon:'check',title:`${_t("Dépôt crédité : +{0}",[F.usd(d.usd)])}`,text:_t("Ton solde est à jour."),href:'#depot'});}
function depRendu(){if((S.ui.route||'')==='depot')render(false);}
const depNotifTxt=d=>d.method?`${_t("Dépôt crédité : {0} ({1}).",[F.usd(d.usd),d.net])}`:`${_t("Dépôt crédité : {0} ({1} sur {2}).",[F.usd(d.usd),fmtCoin(d.amt,d.coin),d.net])}`;
/* écriture locale : une confirmation tous les `pas` ms, puis le crédit et ce qui en découle (mission, XP du jour, rang, badge) */
function depLocal(d,pas){const ep=S.epoch;const iv=setInterval(()=>{if(ep!==S.epoch){clearInterval(iv);return;}d.conf++;refreshDeps();if(d.conf>=d.need){clearInterval(iv);const before=myRank();S.me.balance+=d.usd;S.me.deposits++;depCredite(d);notif('wallet',depNotifTxt(d),'#depot');mission('dep');if(S.me.depDay!==today()){S.me.depDay=today();gainXP(100);}checkRank(before);checkBadges();save();depRendu();}},pas);}
function refreshDeps(){const el=$('[data-deps]');if(el){el.innerHTML=depsH();fixText(el);}const p=$('[data-pend]');if(p)p.textContent=F.usd(S.me.deps.filter(d=>d.conf<d.need).reduce((a,d)=>a+d.usd,0));}
const WFEE={Base:.05,Ethereum:2,Arbitrum:.1,Solana:.01,Polygon:.05};
/* effets d'un retrait, communs aux deux modes et aux deux familles de moyens (crypto : x.net = réseau ; classique : x.method, x.net = nom du moyen, x.addr = destination) */
const wdRecu=x=>Math.max(0,x.amt-x.fee);
function wdLance(x){updateHeader();toast({icon:'out',title:_t("Retrait en cours"),text:x.method?`${_t("{0} vers {1}",[F.usd(wdRecu(x)),x.addr])}`:`${_t("{0} USDC vers {1}…{2}",[F.d2(wdRecu(x)),x.addr.slice(0,6),x.addr.slice(-4)])}`});render(false);}
const wdNotifTxt=x=>x.method?`${_t("Retrait envoyé : {0} par {1}.",[F.usd(wdRecu(x)),x.net])}`:`${_t("Retrait envoyé : {0} USDC sur {1}.",[F.d2(wdRecu(x)),x.net])}`;
function wdEnvoye(x){toast({tone:'blue',icon:'check',title:_t("Retrait envoyé"),text:x.method?`${_t("{0} par {1}",[F.usd(wdRecu(x)),x.net])}`:`${_t("{0} USDC sur {1}",[F.d2(wdRecu(x)),x.net])}`});const el=$('[data-wds]');if(el){el.innerHTML=wdsH();fixText(el);}}
function wdCheck(){const w=S.ui.wd,f=NETS[w.net].fmt,amt=F.parse(w.amt);const addrOk=ADDR_RE[f].test(w.addr.trim());const fee=WFEE[w.net];return {addrOk,amt,fee,recv:Math.max(0,amt-fee),ok:addrOk&&amt>=5&&amt<=S.me.balance,err:!w.addr?'':!addrOk?`${_t("Adresse invalide pour le réseau {0}.",[w.net])}`:amt&&amt<5?_t("Retrait minimum : 5 USDC."):amt>S.me.balance?_t("Montant supérieur à ton solde."):''};}
function wdCalcH(){const c=wdCheck(),w=S.ui.wd;return `${c.err?`<p class="sub c-no">${c.err}</p>`:''}<div class="line"><span>${_t("Frais du réseau {0}",[w.net])}</span><b>${F.usd(c.fee)}</b></div><div class="line"><span>${_t("Tu reçois")}</span><b>${F.d2(c.recv)} USDC</b></div><button class="btn b-pri lg full" data-a="withdraw"${c.ok?'':' disabled'}>${_t("Retirer {0}",[c.amt?F.d2(c.amt)+' USDC':''])}</button>`;}
function vWithdraw(){const w=S.ui.wd,crypto=wMethod()==='crypto';
 const tete=`<div class="pagehead"><div><h1 class="ptitle">${_t("Retirer des fonds")}</h1><p class="plead">${_t("Ton retrait est prélevé en dollars sur ton solde.")}</p></div><div class="seg"><a href="#depot" class="p-2-3 r-sm t-2 fw-5 c-3">${_t("Déposer")}</a><button class="on">${_t("Retirer")}</button></div></div>`;
 /* crypto : 1. le réseau, 2. l'adresse, le montant et le bouton */
 const w1=`<section class="pn pad step"><div class="step-h"><i>1</i><h3>${_t("Choisis le réseau")}</h3></div><div class="nets">${COINS.USDC.nets.map(n=>`<button class="net${w.net===n?' on':''}" data-a="wnet" data-v="${n}"><span class="rad"></span><span class="nn"><b>${n}</b><small>${NETS[n].d}</small></span><span class="nf">${_t("Frais : {0}",[F.usd(WFEE[n])])}<small>${NETS[n].time}</small></span></button>`).join('')}</div></section>`;
 const w2=`<section class="pn pad step"><div class="step-h"><i>2</i><h3>${_t("Adresse et montant")}</h3></div><div class="field"><label for="wa">${_t("Adresse de ton portefeuille sur {0}",[w.net])}</label><input id="wa" data-wd="addr" value="${esc(w.addr)}" placeholder="${NETS[w.net].fmt==='evm'?'0x…':_t("Adresse")}" autocomplete="off" spellcheck="false"><span class="demo-h">${demoB()}<button class="link t-2" data-a="wd-test">${_t("Utiliser une adresse de test")}</button></span></div><div class="field"><label for="wm">${_t("Montant en USDC")}</label><label class="amt"><input id="wm" data-wd="amt" inputmode="decimal" value="${esc(w.amt)}" placeholder="0"><button class="btn b-ghost sm" data-a="wd-max">${_t("Max")}</button></label></div><div class="col gap-3" data-wdcalc>${wdCalcH()}</div></section>`;
 const dispo=`<section class="pn pad"><div class="sub m-0">${_t("Disponible au retrait")}</div><div class="num balbig" data-bal>${F.bal(S.me.balance,true)}</div></section>`;
 const recents=`<section class="pn pad"><div class="h2 mb-1">${_t("Retraits récents")}</div><div data-wds>${wdsH()}</div></section>`;
 if(!argentOrdi())return `<div class="wrap">${tete}
 <div class="g-dep"><div class="col">${methodsH('wd')}${crypto?w1+w2:fiatWdH()}</div>
 <aside class="col">${dispo}${recents}</aside></div></div>`;
 /* ordinateur : le moyen et le solde, le réseau (ou le montant), puis l'adresse, le montant et le bouton, sur trois colonnes */
 const fi=crypto?null:fiatWdParts();
 return `<div class="wrap argx">${tete}<div class="grille12 argx-g"><div class="col argx-m">${methodsH('wd')}${dispo}</div><div class="col argx-f">${crypto?w1:fi[0]}${recents}</div><div class="col argx-s">${crypto?w2:fi[1]}</div></div></div>`;}
function wdsH(){return S.me.wds.length?S.me.wds.slice(0,6).map(x=>x.method?fiatWdRow(x):`<div class="dep"><span class="tk">USDC</span><span class="dd">${_t("<b>{0} USDC sur {1}</b>",[F.d2(x.amt),x.net])}<small>${_t("Vers {0}…{1}, {2}",[esc(x.addr.slice(0,6)),esc(x.addr.slice(-4)),ago(x.at)])}</small></span>${x.st==='sent'?`<span class="st-ok">${_t("{0} Envoyé",[ic('check',13,'currentColor',2.6)])}</span>`:`<span class="st-wait">${_t("En cours d’envoi")}<span class="bar"><i class="w-60"></i></span></span>`}</div>`).join(''):`<p class="sub">${_t("Aucun retrait pour l’instant.")}</p>`;}

/* ===================== Recherche ===================== */
/* C5 : résultats groupés (Marchés, Joueurs, Éclair), texte cherché en gras, probabilité à droite */
function hlq(t,q){t=String(t);const n=norm(t),i=q?n.indexOf(q):-1;if(i<0||n.length!==t.length)return esc(t);return esc(t.slice(0,i))+'<b class="hl">'+esc(t.slice(i,i+q.length))+'</b>'+esc(t.slice(i+q.length));}
function searchRes(q){q=norm(q.trim());if(!q)return [];const M=[],P=[],E=[];
 for(const g of GROUPS)if(norm(g.q+' '+g.short+' '+g.cat+' '+_t(g.cat)).includes(q))M.push({href:'#marche-'+g.id,l:g.short,s:_t(g.cat),r:_t('{0} issues',[g.outcomes.length])});
 for(const m of MARKETS)if(norm(m.q+' '+m.short+' '+m.cat+' '+_t(m.cat)).includes(q))M.push({href:'#marche-'+m.id,l:m.short,s:_t(m.cat),r:F.pct(m.p),p:1});
 for(const u of USER_IDS)if(norm(userOf(u).n).includes(q))P.push({href:'#joueur-'+u,l:userOf(u).n,s:rankName(userOf(u).t,userOf(u).d),u});
 if('eclair'.includes(q)||q.includes('eclair')||norm(_t('Pari éclair')).includes(q))E.push({href:'#eclair',l:_t('Pari éclair'),s:_t('Une manche toutes les 45 secondes'),bolt:1});
 for(const d of GAMES)if(norm(d.name+' '+d.code).includes(q))E.push({href:'#eclair',l:d.name,s:_t(d.cat),r:d.code,bolt:1,fg:d.id});
 return [[_t('Marchés'),M.slice(0,5)],[_t('Joueurs'),P.slice(0,3)],[_t('Éclair'),E.slice(0,3)]].filter(g=>g[1].length);}
/* Recherche plein écran (loupe du header) : le même champ et les mêmes résultats que la recherche habituelle. */
function searchOpen(){let o=$('#sov');if(o){o.remove();return;}ovRemember();const um=$('#umenu');if(um)um.remove();const np=$('#npanel');if(np)np.remove();o=document.createElement('div');o.id='sov';o.className='sov';o.setAttribute('role','dialog');o.setAttribute('aria-label',_t('Rechercher'));
 o.innerHTML=`<div class="sov-in"><div class="sov-h"><div class="search sfull">${ic('search',18)}<input data-search placeholder="${_t('Rechercher un marché ou un joueur')}" autocomplete="off" enterkeyhint="search" aria-label="${_t('Rechercher')}"><div class="sres"></div></div><button class="x" data-a="search-close" aria-label="${_t('Fermer')}">${ic('x')}</button></div></div>`;
 o.addEventListener('click',e=>{if(e.target===o||e.target.closest('.sres a'))setTimeout(searchClose,0);});document.body.appendChild(o);$('input',o).focus();}
function searchClose(){const o=$('#sov');if(o)o.remove();}
let SRN=0;
function showSearch(inp){const box=inp.parentElement.querySelector('.sres'),q=inp.value.trim(),nq=norm(q),G=searchRes(inp.value),sid='sr'+(++SRN)+'-';let n=0;
 const item=x=>{const i=n++;return `<a href="${x.href}"${x.fg?` data-a="fopen" data-v="${x.fg}"`:''} role="option" id="${sid}${i}" class="${i===0?'sel':''}" aria-selected="${i===0}">${x.u?avH(x.u,28,'span'):x.bolt?`<span class="sr-i">${ic('bolt',14)}</span>`:''}<span class="sr-l"><span class="sr-t">${hlq(x.l,nq)}</span><small>${hlq(x.s,nq)}</small></span>${x.r?`<b class="sr-r${x.p?' num':''}">${x.r}</b>`:''}</a>`;};
 box.innerHTML=G.length?G.map(([t,L])=>`<div class="sr-g" role="presentation">${esc(t)}</div>${L.map(item).join('')}`).join('')
  :(q?`<div class="sr-0"><b>${_t('Aucun résultat pour « {0} »',[esc(q)])}</b><span>${_t('Essaie une catégorie :')}</span><div class="sr-cats">${CATS.slice(1).map(c=>`<a class="chip" href="#accueil" data-a="cat" data-v="${c}">${_t(c)}</a>`).join('')}</div></div>`:'');
 box.setAttribute('role','listbox');box.classList.toggle('open',!!q);inp.removeAttribute('aria-activedescendant');fixText(box);}
/* navigation au clavier dans les résultats : ↑ ↓ pour choisir, Entrée pour ouvrir */
document.addEventListener('keydown',e=>{const t=e.target;if((e.key!=='ArrowDown'&&e.key!=='ArrowUp')||!t.dataset||t.dataset.search===undefined)return;const L=[...t.parentElement.querySelectorAll('.sres a[role=option]')];if(!L.length)return;e.preventDefault();
 const i=(L.findIndex(a=>a.classList.contains('sel'))+(e.key==='ArrowDown'?1:-1)+L.length)%L.length;L.forEach((a,k)=>{a.classList.toggle('sel',k===i);a.setAttribute('aria-selected',k===i);});L[i].scrollIntoView({block:'nearest'});t.setAttribute('aria-activedescendant',L[i].id);});
document.addEventListener('click',e=>{const a=e.target.closest?e.target.closest('.sres a'):null;if(!a)return;const s=a.closest('.search'),i=s&&s.querySelector('[data-search]');if(i){i.value='';i.blur();}$$('.sres').forEach(x=>x.classList.remove('open'));});

