function toggleNotifs(){let p=$('#npanel');if(p){p.remove();return;}p=document.createElement('div');p.id='npanel';p.className='npanel';p.innerHTML=`<div class="nh">${_t("<b>Notifications</b>")}<span class="nh-r">${S.me.notifs.length?`<button class="link" data-a="np-clear">${_t("Tout effacer")}</button>`:''}<button class="x" data-a="npanel-close" aria-label="${_t("Fermer")}">${ic('x',16)}</button></span></div>${S.me.notifs.length?S.me.notifs.map((n,i)=>`<div class="nitem${n.read?'':' unread'}"><a class="nlink" href="${n.href||'#accueil'}" data-a="npanel-close"><span class="ni">${ic(n.ic||'info',16)}</span><span>${esc(sansPoint(n.text))}<small>${ago(n.at)}</small></span></a><button class="nx" data-a="np-del" data-i="${i}" aria-label="${_t('Effacer cette notification')}" title="${_t('Effacer')}">${ic('x',14)}</button></div>`).join(''):`<div class="empty">${_t("Rien de neuf pour l’instant")}</div>`}${npModeH()}`;document.body.appendChild(p);fixText(p);const nonLues=S.me.notifs.some(n=>!n.read);S.me.notifs.forEach(n=>n.read=true);updateBell();if(SRV()){if(nonLues)API.call('api_notifs_read').catch(()=>{});}else save();}

