 cite:a=>citeModal(a.dataset.room),
 'cite-pick':a=>{const rid=a.dataset.room;closeModal();const i=$(`[data-in="${CSS.escape(rid)}"]`);if(i){i.value=(i.value.trim()?i.value.trim()+' ':'')+'#'+a.dataset.m+' ';i.focus();}},
