 copylink:a=>copyText(SITE_URL+'/'+a.dataset.v,_t("Lien copié")),'search-open':()=>searchOpen(),'search-close':()=>searchClose(),copy:a=>copyText(a.dataset.v,_t("Adresse copiée")),
